INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_100101_001", "どんなに敵が大勢でも、みんなで\n力を合わせれば絶対大丈夫だよ！\nだから顔を上げてこう！\nごーごー！", 1, 0, 100101, "", "vo_empress_100101_001", "ヒヨリ", 1, 5, 1);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_100101_002", "ううっ、何度も戦う相手もいるけど\nあたし、負けたりなんてしないよ！\n今回だってみんなや騎士くんがいる\nフルパワーでいくよーっ！", 1, 0, 100103, "", "vo_empress_100101_002", "ヒヨリ", 1, 5, 2);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_100101_003", "うぅ…すごい力…！\n…でも、なんだか悲しそう\nこの人の気持ちを知りたい\nだからこそ…勝たなきゃ…！", 2, 0, 100103, "", "vo_empress_100101_003", "ヒヨリ", 1, 5, 3);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_100101_004", "騎士くんの力があれば、\nあたしは絶対負けないよ！\nみんなが笑顔でいられるように\n一緒にがんばろう！", 3, 100101, 100102, "", "vo_empress_100101_004", "ヒヨリ", 1, 5, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_100201_001", "わたしたちの世界のためにも\nこの世界のためにも、\n絶対に負けられない…！\nがんばろうね、騎士クン", 1, 0, 100203, "", "vo_empress_100201_001", "ユイ", 1, 5, 5);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_100201_002", "みんな、怪我したらすぐに教えて！\n…もう誰も失いたくないの\nそのために修行もしたんだから…\n大丈夫、絶対なんとかしてみせる！", 1, 0, 100203, "", "vo_empress_100201_002", "ユイ", 1, 5, 6);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_100201_003", "世界を『書き換え』するなんて…\nそんな未来、寂しいだけだよ…！\nお願い、これ以上みんなを\n傷つけないで…話を聞いて！", 2, 0, 100203, "", "vo_empress_100201_003", "ユイ", 1, 5, 7);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_100201_004", "感じるよ、騎士クンの気持ち…\n抱きしめられてるみたいに\nあったかい…\nぜんぶ終わらせよう！", 3, 100201, 100202, "", "vo_empress_100201_004", "ユイ", 1, 5, 8);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_100301_001", "厳しい戦いになるだろうな\n安心してくれ、何があっても\nキミは守る。…いや、違うな\n一緒に、世界を守ろう", 1, 0, 100301, "", "vo_empress_100301_001", "レイ", 1, 5, 9);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_100301_002", "手ごわい相手ばかりだな…\nだが引き下がるわけにはいかない\nこちらにだって譲れないものが\nあるんだ！", 1, 0, 100303, "", "vo_empress_100301_002", "レイ", 1, 5, 10);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_100301_003", "くっ…なんて力だ…！\n防ぐだけで精一杯…だが、\n例え剣が折れたとしても、\n私は最後まで戦い続ける！", 2, 0, 100303, "", "vo_empress_100301_003", "レイ", 1, 5, 11);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_100301_004", "感じるよ、キミからの愛\nこれがあれば、私はどんな\n敵にだって打ち勝てる！\n見せてやろう、一緒に！", 3, 100301, 100302, "", "vo_empress_100301_004", "レイ", 1, 5, 12);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_100401_001", "ミソギとにいちゃんはこれからも\n世界中を冒険して、ワクワクする\nお宝をたくさん見つけるんだ！\nワルモノなんかに邪魔させないよ！", 1, 0, 100401, "", "vo_empress_100401_001", "ミソギ", 1, 5, 13);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_100401_002", "わわ、なんかヤバそうな雰囲気…\nこういう時こそミソギの出番だね！\nとっておきのイタズラ決めて、\nピンチもひっくり返しちゃうよ！", 1, 0, 100401, "", "vo_empress_100401_002", "ミソギ", 1, 5, 14);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_100401_003", "うぅ…あの悪者、すごい迫力だよ…\nもしミソギたちが負けちゃったら、\nミソギもにいちゃんもこの世界も…\n全部おしまい、なんだよね…？", 2, 0, 100403, "", "vo_empress_100401_003", "ミソギ", 1, 5, 15);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_100401_004", "ミソギたちが世界を救っちゃったら\nきっとみんなびっくりするよね！\nどんな顔して驚いてくれるかな…\nにひひ、なんかワクワクしてきた！", 3, 100401, 100402, "", "vo_empress_100401_004", "ミソギ", 1, 5, 16);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_100501_001", "歴代オールヒーロー大進撃ッス～！\n自分は新世代のエースってとこッス\nかね？　さあ、ついてくるッス……\nあれ？　みんなどこ？　待って～", 1, 0, 100501, "", "vo_empress_100501_001", "マツリ", 1, 5, 17);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_100501_002", "敵は圧倒的な力で、こっちを絶望\nさせる気ッスかね？　だとしたら\n大誤算ッスよ！　むしろ自分の\n正義の魂に火をつけたんスから！", 1, 0, 100501, "", "vo_empress_100501_002", "マツリ", 1, 5, 18);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_100501_003", "足が……震えるッス……けど！\nこれは武者震いッス……！　だって\nヒーローは絶対に絶対にっ！\n敗北なんてしないんスから……っ！", 2, 0, 100503, "", "vo_empress_100501_003", "マツリ", 1, 5, 19);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_100501_004", "さあ、手と手をつないで、\n二人で教えてやるッスよ！\nどんな物語でも、悪は必ずヒーロー\nに打ち倒されるってことを！", 3, 100501, 100502, "", "vo_empress_100501_004", "マツリ", 1, 5, 20);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_100601_001", "ひゃぁんっ！\nもう、敵さんが脅かしてくるから\nアカリ、ヘンな声出ちゃいました…\nこういうの、よくないですよっ", 1, 0, 100603, "", "vo_empress_100601_001", "アカリ", 1, 5, 21);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_100601_002", "アカリ、お兄ちゃんとシタイコトが\nまだまだいっぱいあるんです！\nだから、私たちの大事な世界も…\n本気で守り抜いてみせますっ！", 1, 0, 100601, "", "vo_empress_100601_002", "アカリ", 1, 5, 22);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_100601_003", "うぅ…こんなに激しく攻められたら\nアカリ、もう壊れちゃいそうです…\nだけどまだまだ…戦えますっ！\nお兄ちゃんが一緒なんですからっ…", 2, 0, 100603, "", "vo_empress_100601_003", "アカリ", 1, 5, 23);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_100601_004", "お兄ちゃんの愛を注いでもらって\nアカリ超絶パワーアップです！\nアカリらしく世界一かわいく、\n世界を救ってみせちゃいますよ！", 3, 100601, 100602, "", "vo_empress_100601_004", "アカリ", 1, 5, 24);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_100701_001", "アイツらが野放しだと、ミヤコは\n安心してプリンを食べられないの\n今日のプリンと明日のプリンの\nためにも、絶対負けないの！", 1, 0, 100701, "", "vo_empress_100701_001", "ミヤコ", 1, 5, 25);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_100701_002", "前はミヤコ、悪いヤツに捕まって\n消されそうになって怖かったの…\nでも今度は全然怖くないの！\nオマエが一緒なら平気なの！", 1, 0, 100702, "", "vo_empress_100701_002", "ミヤコ", 1, 5, 26);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_100701_003", "むうぅ～っ、アイツしつこいの！\nこうなったら、オマエにも\nミヤコのプリン分けてやるの！\nダブルプリンパワーで頑張るの！", 2, 0, 100703, "", "vo_empress_100701_003", "ミヤコ", 1, 5, 27);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_100701_004", "アイツはどんなに強くたって、\n独りぼっちのさびしいヤツなの\nでもオマエにはミヤコがいるの！\nミヤコたちなら絶対に勝てるの！", 3, 100701, 100702, "", "vo_empress_100701_004", "ミヤコ", 1, 5, 28);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_100801_001", "相手が誰であれ、やることは同じ…\nそう…ボクの美しさを見せてあげる\nことさ！　予言しよう…絶世の美の\n前にはどんな敵もひれ伏すと、ね！", 1, 0, 100801, "", "vo_empress_100801_001", "ユキ", 1, 5, 29);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_100801_002", "少し待っていてくれる？　メイクを\n直さないと。避けられない戦いなら\nせめて美しいボクと戦えることを\n彼らには誇りに思ってほしいからね", 1, 0, 100801, "", "vo_empress_100801_002", "ユキ", 1, 5, 30);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_100801_003", "どうせ倒れるなら美しいままで散り\nたいな。ふふ、難しい望みかな…？\nそれでもボクは、最後まで美しく\nあがいてみせるよ、キミと一緒にね", 2, 0, 100801, "", "vo_empress_100801_003", "ユキ", 1, 5, 31);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_100801_004", "ボクがいて、キミがいる。ボクたち\nが勝つのに、これ以上の理由はない\nよね。だって美しい者が勝つ未来の\nほうが、美しいエンディングだもの", 3, 100801, 100802, "", "vo_empress_100801_004", "ユキ", 1, 5, 32);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_100901_001", "災厄の嵐が吹き荒れ、世界の命運は\n風前の灯が如く儚い。だが絶望には\nまだ早い！　希望はここに在り！\n灯火を掲げよう、盟友シグルドよ！", 1, 0, 100901, "", "vo_empress_100901_001", "アンナ", 1, 5, 33);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_100901_002", "終焉の日、滅びの刻来たれり、か…\nだが、幾度も転生を繰り返しながら\n戦いつづけた我らの宿命を思えば、\nこの程度取るに足らない…はずだ！", 1, 0, 100903, "", "vo_empress_100901_002", "アンナ", 1, 5, 34);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_100901_003", "くっ…なんという禍々しい魔力…！\nもはや世界の滅びも間近…しかし\n疾風の冥姫がここで退くわけには\nいかぬ！　しぶとく抗ってみせるぞ", 2, 0, 100903, "", "vo_empress_100901_003", "アンナ", 1, 5, 35);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_100901_004", "永遠の盟約で結ばれし魂の伴侶…\n世界を滅ぼさんとする災禍の剣も\nこの絆を断ち切ることはできない！\n覚悟するがいい、幻境竜后！！", 3, 100901, 100902, "", "vo_empress_100901_004", "アンナ", 1, 5, 36);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_101001_001", "【自警団】のギルドマスターとして\nしゃんとして恥ずかしない姿を\n見せなあきまへんなぁ…王子はん\nしゃなりしゃなり、いきまひょ！", 1, 0, 101001, "", "vo_empress_101001_001", "マホ", 1, 5, 37);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_101001_002", "王子はん、服が破れてますえ？\nこれでよし…うん、完璧や♪\n戦いの中でも、王子はんには\n格好良う居てもらいたいさかいに♪", 1, 0, 101001, "", "vo_empress_101001_002", "マホ", 1, 5, 38);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_101001_003", "幻境竜后…大層なお名前してはる\nお后さまが勝負を挑んできはるなら\nうちも、マホマホ王国の姫として…\n正々堂々受けて立ちますえ！", 2, 0, 101003, "", "vo_empress_101001_003", "マホ", 1, 5, 39);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_101001_004", "強い愛で結ばれた王子と姫を\n引き裂くことは誰にもできまへん\n王子はん…ふたりで一緒に！\nハッピーエンドを迎えまひょ！", 3, 101001, 101002, "", "vo_empress_101001_004", "マホ", 1, 5, 40);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_101101_001", "お兄ちゃんがいれば百人力士っ！\n妹パワーも全開でいきますよ～♪\nどんな敵でもドンドンこいですっ！\nあれ？　ちょっと違いました？", 1, 0, 101101, "", "vo_empress_101101_001", "リノ", 1, 5, 41);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_101101_002", "これぞまさに『四面そば』…\n敵多すぎでもう大盛りですけど\n秘密結社の一員として、妹として\nこの世界の平和は守り通しますっ！", 1, 0, 101101, "", "vo_empress_101101_002", "リノ", 1, 5, 42);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_101101_003", "あれが幻境竜后…不思議な服…\nじゃなくて、空気がピリピリです…\nちょっとだけ怖いけど…妹として\n絶対に降参なんてしませんよ！", 2, 0, 101103, "", "vo_empress_101101_003", "リノ", 1, 5, 43);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_101101_004", "私、もう迷いません！\nお兄ちゃんと一緒なら\nどんな敵だって倒しちゃいます！\n妹のポテンシャルは無限大ですよ！", 3, 101101, 101102, "", "vo_empress_101101_004", "リノ", 1, 5, 44);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_101201_001", "どんなに大変な時でもキミと一緒に\nず～っと乗り越えてきたんだもん！\nだからっ、今回もきっと大丈夫！\n私の魔法できらーん☆　だよっ！", 1, 0, 101201, "", "vo_empress_101201_001", "ハツネ", 1, 5, 45);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_101201_002", "力を使いすぎると眠く…スヤァ…\nはっ、いけないいけない！\nキミ、私が寝ちゃったら起こして！\n…お、王子様のキスとかで…", 1, 0, 101202, "", "vo_empress_101201_002", "ハツネ", 1, 5, 46);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_101201_003", "も～！　容赦なさすぎだよぉ！\nそっ、それにさっきまでの戦いの\nせいで、ね、眠気がぁ～っ…\nハ、ハツネちゃん、ピ～ンチ…", 2, 0, 101203, "", "vo_empress_101201_003", "ハツネ", 1, 5, 47);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_101201_004", "幻境竜后さんがどんなに強くても\n今のハツネちゃんは無敵なのだ～！\n大好きなキミと！　シオリンと！\nみんながいる世界を守っちゃうよ！", 3, 101201, 101202, "", "vo_empress_101201_004", "ハツネ", 1, 5, 48);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_101301_001", "この世界にはね、たくさんの人の\n『好き』が詰まってるんだよ\nそれをぶち壊すなんて鬼畜の所業\nナナカちゃんが許しはしないぜ！", 1, 0, 101301, "", "vo_empress_101301_001", "ナナカ", 1, 5, 49);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_101301_002", "見るからにヤバい奴らが勢ぞろい！\nでもみんなの世界が狙われてんのに\n日和ってる奴いる？いねえよなぁ！\n全員ぶっ飛ばして世界を救うぞ！！", 1, 0, 101301, "", "vo_empress_101301_002", "ナナカ", 1, 5, 50);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_101301_003", "あとはラスボスを倒せば勝利ッ！\n第３部完！　…とはいかない感じ？\nていうか逆にピンチな気配？\nどっどうしよう、どうすれば！？", 2, 0, 101303, "", "vo_empress_101301_003", "ナナカ", 1, 5, 51);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_101301_004", "幻境竜后…確かに強敵だったね\nでも今はもう負ける気がしないかな\nだって私は、ただのナナカじゃない\n超ナナカちゃんだから…！", 3, 101301, 101302, "", "vo_empress_101301_004", "ナナカ", 1, 5, 52);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_101401_001", "あちらにもなかなかの陰謀家がいる\nようだね。彼女らの最大の誤算は\nここに希代の名探偵がいることさ！\nさあ助手くん。真実を勝ち取ろう！", 1, 0, 101401, "", "vo_empress_101401_001", "カスミ", 1, 5, 53);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_101401_002", "仕方ない、こうなったら奥の手だ\nミスティ！　セオリー！　…って\nこらぁっ！　変身の最中は待って\nくれるのがお約束だよ！？", 1, 0, 101401, "", "vo_empress_101401_002", "カスミ", 1, 5, 54);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_101401_003", "なっ…なんだい、この悪寒は…\n触れてはならない何か…いいや！\n名探偵たるもの巨悪に恐れをなす\nわけにはいかない。絶対に…！", 2, 0, 101403, "", "vo_empress_101401_003", "カスミ", 1, 5, 55);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_101401_004", "どんな哀しみでさえ、道理を穢す\n理由にしてはならない。さあ、\nお縄につくんだ。史上最大の迷宮\n事件…終わらせるのは…この私だ！", 3, 101401, 101402, "", "vo_empress_101401_004", "カスミ", 1, 5, 56);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_101501_001", "先生は…ううん、先生たちは。\n絶対に負けません。みんなに傷一つ\nつけさせたりはしないわ…！", 1, 0, 101501, "", "vo_empress_101501_001", "ミサト", 1, 5, 57);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_101501_002", "とっても強大な敵ばかりね…\nでも、大丈夫。焦らず落ち着いて\n戦いましょう。先生がついてるわ\n長引いても、あきらめないで…！", 1, 0, 101501, "", "vo_empress_101501_002", "ミサト", 1, 5, 58);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_101501_003", "幻境竜后さんの力…すごいわ…\nううん、怖がってる暇なんてないの\n森のみんなを守るためにも…！\n好き勝手したら「めっ」ですからね", 2, 0, 101501, "", "vo_empress_101501_003", "ミサト", 1, 5, 59);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_101501_004", "あなたと一緒なら\n負けたりなんか絶対にしないわ\n最後の一撃まで、\nがんばりましょうね♪", 3, 101501, 101502, "", "vo_empress_101501_004", "ミサト", 1, 5, 60);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_101601_001", "ツヨそーな敵ばっかりで\nテン下げってカンジだけど\nとりま、うちとヒデサイが\n一緒なら乗り越えられるっしょ！", 1, 0, 101601, "", "vo_empress_101601_001", "スズナ", 1, 5, 61);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_101601_002", "あっ、まってヒデサイ\nマントずれてるから直してあげる\n…よし！　こーゆう時こそ\nおしゃれでテン上げしなきゃね♪", 1, 0, 101601, "", "vo_empress_101601_002", "スズナ", 1, 5, 62);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_101601_003", "おにヤバすぎて超わろ～…でもでも\nどうにかやるしかないっしょ～\n勝利のランウェイ遠すぎだけど\nうちら諦めんのはダメだよね～！", 2, 0, 101601, "", "vo_empress_101601_003", "スズナ", 1, 5, 63);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_101601_004", "アオハルでバイブス爆上げ♪\n今のうちらは、ムテキだよ～\nハッピーで、もにカワな未来だって\n一緒にゲットするしかないっしょ♪", 3, 101601, 101602, "", "vo_empress_101601_004", "スズナ", 1, 5, 64);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_101701_001", "歌ったり踊ったり、\nキミと一緒にやりたいことが\nばんないあるからね～！\n絶対に負けられないさ～！", 1, 0, 101701, "", "vo_empress_101701_001", "カオリ", 1, 5, 65);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_101701_002", "ううっ強そうな敵ばっかりさ～！\n長丁場の戦いにはやっぱりこれよ～\nサーターアンダギー！\n栄養付けて平和を守るさ～♪", 1, 0, 101701, "", "vo_empress_101701_002", "カオリ", 1, 5, 66);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_101701_003", "うぅ～、幻境竜后、でーじ強いね～\n私たちも引き下がる気はないよ～！\nどんなに時間がかかっても、絶対に\n諦めたりしないさ～！　だよね～？", 2, 0, 101703, "", "vo_empress_101701_003", "カオリ", 1, 5, 67);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_101701_004", "キミのくれた情熱が、\n私の中で熱く燃え滾ってるよ！\n最高の一撃、キミに見せるさ～！", 3, 101701, 101702, "", "vo_empress_101701_004", "カオリ", 1, 5, 68);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_101801_001", "学校生活の邪魔はさせないわ\nだって私、みんなの先生だもの\n明日の授業も世界のことも\n全部守ってみせるんだから！", 1, 0, 101801, "", "vo_empress_101801_001", "イオ", 1, 5, 69);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_101801_002", "やん！　なんて手ごわい人たちなの\nでも諦めないわ。難しい問題だって\n落ち着いてやればちゃんと解けるの\n戦いも同じよ…いきましょう！", 1, 0, 101801, "", "vo_empress_101801_002", "イオ", 1, 5, 70);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_101801_003", "これが、幻境竜后さんの力…圧倒\nされちゃいそう。でも、怖がってる\n場合じゃないわ。先生は絶対に、\nここから退かないわ！", 2, 0, 101803, "", "vo_empress_101801_003", "イオ", 1, 5, 71);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_101801_004", "二人の絆があれば、\n怖いものなんてないわ\n先生と力を合わせて─\nいきましょう♪", 3, 101801, 101802, "", "vo_empress_101801_004", "イオ", 1, 5, 72);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_102001_001", "す、すごく強そうな人がいっぱい…\nミミ、怖くてぶるぶるしちゃうけど\nでも泣いちゃったりはしないよっ\nおにいちゃんがいっしょだもん…！", 1, 0, 102003, "", "vo_empress_102001_001", "ミミ", 1, 5, 73);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_102001_002", "プチグリフォンさんもハナちゃんも\nみゅ～ちゃんも…きっとみんな、\nミミのこと応援してくれてるよね\nだからミミも、がんばるよっ…！", 1, 0, 102003, "", "vo_empress_102001_002", "ミミ", 1, 5, 74);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_102001_003", "あ、あの竜の人…本気になったら、\nすごく強そうだよ…！このままじゃ\nみんなもミミたちも負けちゃう…？\nやだ、ミミそんなのいやだよっ…", 2, 0, 102003, "", "vo_empress_102001_003", "ミミ", 1, 5, 75);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_102001_004", "おにいちゃんがくれた元気、\n今度はミミたちから届けようね\nもう大丈夫、心配しないでって…\n世界中の、大切なお友だちに…！", 3, 102001, 102002, "", "vo_empress_102001_004", "ミミ", 1, 5, 76);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_102101_001", "怖い人たちがいっぱいですぅ…！\n…でも、みんな頑張ってる…私も\nベルルちゃんみたいに勇気を出して\n…祝福の音を鳴らしましょう！", 1, 0, 102101, "", "vo_empress_102101_001", "クルミ", 1, 5, 77);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_102101_002", "お兄ちゃん、私、がんばりますぅ\n『ロスト』したお父さんたちの\nためにも…！　怖い時こそ前を見て\n戦ってみせますからっ…！", 1, 0, 102101, "", "vo_empress_102101_002", "クルミ", 1, 5, 78);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_102101_003", "っ…すごい迫力ですぅ…！\nでも…絶望は必ず乗り越えられる\n胸の中の、希望の音色を信じて…\n逃げたりなんか、しませんよぅ…っ", 2, 0, 102101, "", "vo_empress_102101_003", "クルミ", 1, 5, 79);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_102101_004", "みんなに勇気を与えるために\n主役にも英雄にもなってみせますぅ\nお兄ちゃんがいてくれるなら\n私はなんでもできるんです…！", 3, 102101, 102102, "", "vo_empress_102101_004", "クルミ", 1, 5, 80);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_102201_001", "こ、これくらいの敵、問題ないわ！\nほんとはちょっと怖いけど…\nゲームの世界を救うことくらい\nこっちは慣れっこなんだから…！", 1, 0, 102201, "", "vo_empress_102201_001", "ヨリ", 1, 5, 81);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_102201_002", "ここで私たちが負けたら、\n世界が終わっちゃうなんて…\n絶対に認めるわけにはいかないわ！\nアンタも覚悟決めなさいよっ！", 1, 0, 102201, "", "vo_empress_102201_002", "ヨリ", 1, 5, 82);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_102201_003", "ここからが本当の戦いってこと？\nならもう、とことんやってやるわ！\nゲーマーってのは、敵が手強いほど\n燃えてくる生き物なのよ！", 2, 0, 102203, "", "vo_empress_102201_003", "ヨリ", 1, 5, 83);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_102201_004", "絶対に帰りたい理由ができた…\nそう思うだけで、いくらでも力が\n湧いてくるの。これならもう、\n文句なしの勝ち確よねっ！", 3, 102201, 102202, "", "vo_empress_102201_004", "ヨリ", 1, 5, 84);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_102301_001", "私もみんなと一緒に戦うよ！\n悪い人たちはフルスイングで\nあっという間に倒しちゃうから！\n『おうっ！　全員かかってこい！』", 1, 0, 102301, "", "vo_empress_102301_001", "アヤネ", 1, 5, 85);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_102301_002", "本当はちょっとだけ怖いけど…\nぷうきちもお兄ちゃんも一緒だもん\n力を合わせて世界を守っちゃうよ\n絶対に負けないんだから！", 1, 0, 102303, "", "vo_empress_102301_002", "アヤネ", 1, 5, 86);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_102301_003", "ううっあの人、すごく怖いけど\n逃げないよ、戦うって決めたもん\nね、お兄ちゃん、ぷうきち！\n『ここが踏ん張りどころだぞ！』", 2, 0, 102303, "", "vo_empress_102301_003", "アヤネ", 1, 5, 87);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_102301_004", "お兄ちゃんが約束してくれたもん\n今の私ならどんな悪いやつにも\n負けないよ！　宇宙人でもなんでも\n一撃で追い返しちゃうんだから♪", 3, 102301, 102302, "", "vo_empress_102301_004", "アヤネ", 1, 5, 88);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_102501_001", "大変なことになっちゃいましたね…\nで、でも怖がっていられません！\nお嬢さまのことも、あなたのことも\n私が精一杯お支えします！", 1, 0, 102503, "", "vo_empress_102501_001", "スズメ", 1, 5, 89);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_102501_002", "世界の命運がかかってますから\nドジなんてしてられません！\n…って、ああっ！　言ったそばから\nまた魔法が暴走しちゃいましたっ！", 1, 0, 102503, "", "vo_empress_102501_002", "スズメ", 1, 5, 90);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_102501_003", "す、すごい力です…！\nでもお嬢さまや大切な人をおいて\n逃げるわけにはいきません！\nどこまでもお供します…！", 2, 0, 102503, "", "vo_empress_102501_003", "スズメ", 1, 5, 91);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_102501_004", "大切な人と力を合わせれば、\nドジな私でも世界を救えるんです！\n世界規模…いえ、宇宙規模の大掃除\n始めちゃいますよ～っ！", 3, 102501, 102502, "", "vo_empress_102501_004", "スズメ", 1, 5, 92);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_102601_001", "ええー？　こんだけ人数いるならさ\n一人ぐらいいなくても…\n…って空気じゃないわけね\nはいはい、あたしも働きますよー", 1, 0, 102603, "", "vo_empress_102601_001", "リン", 1, 5, 93);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_102601_002", "うぅ…あんなのもうバグでしょ！？\nこんな無理ゲーに参戦したんだもん\n終わったらしばらく働かないから！\nダラダラゴロゴロするからね～！", 1, 0, 102603, "", "vo_empress_102601_002", "リン", 1, 5, 94);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_102601_003", "見てよあのビジュアルさー\nまさにラスボスって感じじゃん…\nでも、どんなゲームでもボスは\n倒せるわけだし…はぁ、やるかー", 2, 0, 102603, "", "vo_empress_102601_003", "リン", 1, 5, 95);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_102601_004", "ここまで来たら後には退けないし\n正真正銘のラスボス戦ってんなら\nあたしも─気合い入れて\n少しぐらいイイとこ見せないとね！", 3, 102601, 102602, "", "vo_empress_102601_004", "リン", 1, 5, 96);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_102701_001", "有象無象のクズ虫が、私たちの\n幸せを阻もうとしているようですね\nあぁ、なんて忌々しいのでしょう…\n残らずすり潰しますわ、クスクス…", 1, 0, 102701, "", "vo_empress_102701_001", "エリコ", 1, 5, 97);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_102701_002", "クスクス…あら、失礼しましたわ\nこの連中を駆逐すれば、私たちの\n絆はより強く…そんな想像をしたら\n思わず…クスクスクス、クスクス", 1, 0, 102701, "", "vo_empress_102701_002", "エリコ", 1, 5, 98);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_102701_003", "あの女…下らない言葉であなた様を\n誑かそうとしたとか。万死に値する\n罪…身の程を思い知らせてやるまで\n決して退きはしませんわ…", 2, 0, 102703, "", "vo_empress_102701_003", "エリコ", 1, 5, 99);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_102701_004", "『壊し屋』と呼ばれる私ですが…\n今はこの力、創るために振るいます\nあなた様との愛、未来…\nクスクス…さあ参りましょう…♪", 3, 102701, 102702, "", "vo_empress_102701_004", "エリコ", 1, 5, 100);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_102801_001", "しっかり頭数揃えてきたわね…\nでもこの程度の力に屈するような\nあたしたちじゃないんだから\nあんたも、サポート頼んだわよ！", 1, 0, 102801, "", "vo_empress_102801_001", "サレン", 1, 5, 101);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, 1, "vo_empress_102801_002", "ちょっと！　なんか向こうに\n教育に悪そうなのがいるんだけど！\nあいつは子どもたちの目に入る前に\nあたしたちで倒すわよ。いい？", 4002, 0, 102801, 10000, "vo_empress_102801_002", "サレン", 1, 3, 102);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_102801_003", "もう、強すぎて参っちゃうわね…\nでも諦めるわけにはいかないわ\nこっちだって守らなきゃいけない\nものがたくさんあるんだから！", 2, 0, 102803, "", "vo_empress_102801_003", "サレン", 1, 5, 103);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_102801_004", "いつも以上に負ける気がしないわ\nこれもあんたと気持ちが通じた\nおかげね。あんたが側にいる限り、\nあたしはずっと無敵なんだから！", 3, 102801, 102802, "", "vo_empress_102801_004", "サレン", 1, 5, 104);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_102901_001", "この世界が終わっちゃうって…\nアイドル活動も卒業ってコト！？\nファンのみんなが黙ってないよ！\nもちろん私だって…！", 1, 0, 102903, "", "vo_empress_102901_001", "ノゾミ", 1, 5, 105);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_102901_002", "どんな強い敵にだって屈しない…\n歌って踊って戦うアイドルになる！\nあの日に誓った願い、私の希望！\n今こそ、果たして見せるんだから！", 1, 0, 102903, "", "vo_empress_102901_002", "ノゾミ", 1, 5, 106);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_102901_003", "幻境竜后…ダンスも歌も、あなたに\nとって価値はないかもしれないけど\n私はこのステージから逃げたり\nなんてしない！　アイドルとして！", 2, 0, 102903, "", "vo_empress_102901_003", "ノゾミ", 1, 5, 107);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_102901_004", "星を書き換えるなんてすごい発想…\nプロデューサーとか向いてるかも？\nって、今はそんな場合じゃないか！\n覚悟してよね、幻境竜后！", 3, 102901, 102901, "", "vo_empress_102901_004", "ノゾミ", 1, 5, 108);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_103001_001", "ショーグンの天下統一を阻む者は\n誰であろうと許しまセン！\nショーグン！　ここはチューシン\nニノンにお任せアーレー！", 1, 0, 103001, "", "vo_empress_103001_001", "ニノン", 1, 5, 109);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_103001_002", "むむむ…待ち受けているのは強敵\nばかり…それでも退きまセン！\n超烈火之紅蓮旋風で、\nまとめて討ち取ってみせまショウ！", 1, 0, 103001, "", "vo_empress_103001_002", "ニノン", 1, 5, 110);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_103001_003", "な、なんて強さ…このままでは、\nワタシたちは負けてしまいます…\n…いいえ。いいえ！　ショーグンの\nためにも、諦めることなど…っ！", 2, 0, 103003, "", "vo_empress_103001_003", "ニノン", 1, 5, 111);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_103001_004", "感じマス、ショーグンの愛を…！\n今ならどんな敵が来ても、\nカッサイ、ボンサイ、\nオチャノコサイサイデース！", 3, 103001, 103002, "", "vo_empress_103001_004", "ニノン", 1, 5, 112);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_103101_001", "この世界が、明日を迎えることなく\n滅んでしまうかもしれない…\n運命の岐路が、目の前にあります\n抗えるのは、私たちだけです…！", 1, 0, 103101, "", "vo_empress_103101_001", "シノブ", 1, 5, 113);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_103101_002", "何よりも色濃い死の気配が、\n世界に満ちていくのを感じます\nでも、倒れるわけにはいきません\n最後まで戦いましょう、全力で", 1, 0, 103101, "", "vo_empress_103101_002", "シノブ", 1, 5, 114);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_103101_003", "これほどまでに強大な力なんて…\n占いも、未来は滅びの闇に覆われ\nつつある、と出ています…それでも\n希望を手放すわけには…！", 2, 0, 103103, "", "vo_empress_103101_003", "シノブ", 1, 5, 115);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_103101_004", "命ある者にとって、死の運命は\n決して避けられないもの…\nでも、今この時ではないはずです\n戦いましょう、未来のために…！", 3, 103101, 103101, "", "vo_empress_103101_004", "シノブ", 1, 5, 116);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_103201_001", "これ以上の狼藉は許しません！\nウィスタリア家の名に懸けて、\nこの世界の人々を守ります…必ずや\n貴人としての役目を果たしますわ！", 1, 0, 103201, "", "vo_empress_103201_001", "アキノ", 1, 5, 117);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_103201_002", "互いを利するウィンウィンの関係\nそれが商売の鉄則です。力を振るい\n一方的に望みを押し付けるなんて、\n倒産まっしぐらですわよっ！", 1, 0, 103201, "", "vo_empress_103201_002", "アキノ", 1, 5, 118);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_103201_003", "幻境竜后…すさまじい力ですわね\n世界を意のままにするという野望も\n決して絵空事ではないのでしょう…\nそれでも私は…諦めませんわよ！", 2, 0, 103203, "", "vo_empress_103201_003", "アキノ", 1, 5, 119);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_103201_004", "人々を守ることが力ある者の務め…\nそしてあなたさまと共に生きること\nそれが私の務めであり願いですわ！\nこの想いは、止まりませんわよ！", 3, 103201, 103202, "", "vo_empress_103201_004", "アキノ", 1, 5, 120);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_103301_001", "こんな舞台で漫才したって\nみんなもお天道さんもどんよりだべ\n安心して笑ってられる世界を\nオラたちで取り戻すど！　おー！", 1, 0, 103301, "", "vo_empress_103301_001", "マヒル", 1, 5, 121);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_103301_002", "お、おっかねぇ連中だ…！\nでも…スベっちまう怖さに比べりゃ\nマシだべな！　あははっ！\nみんなの笑顔は、オラが守るべ！", 1, 0, 103301, "", "vo_empress_103301_002", "マヒル", 1, 5, 122);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_103301_003", "あの子、芸人として光りそうだべな\n幻境竜后なんて仰々しい名前も…\nノーヴィジョンズノープロブレム！\n…あたた！　激しいツッコミだべ！", 2, 0, 103303, "", "vo_empress_103301_003", "マヒル", 1, 5, 123);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_103301_004", "逆境も笑顔で切り開く…\nあんちゃんと一緒なら\nできる気がすんだ\nオラたちの芸人魂、見せてやるべ！", 3, 103301, 103302, "", "vo_empress_103301_004", "マヒル", 1, 5, 124);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_103401_001", "元…ううん、正しき聖騎士として\nここでやらなきゃいつやるのよ…！\n必ずみんなを守りきってみせるわ\n怪我をした人は私のところへ！", 1, 0, 103401, "", "vo_empress_103401_001", "ユカリ", 1, 5, 125);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_103401_002", "…んぐっ…ごくっ…ぷは～っ♪\nよぉし気合十分らわ～っ！\nこら～幻境竜后～っ！　隠れて\nないでかかってきなさ～い！", 1, 0, 103401, "", "vo_empress_103401_002", "ユカリ", 1, 5, 126);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_103401_003", "ひっく…ふぇ？　な、なに……？\nと、とっても大きいのが見えりゅ…\n…なっ、なによこれえぇぇ！\nこ、これが幻境竜后の姿なのぉ～っ", 2, 0, 103403, "", "vo_empress_103401_003", "ユカリ", 1, 5, 127);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_103401_004", "私は無敵らのよ～♪　この世界と\nキミと築く\n素敵な未来のために…幻境竜后！\nぶっとばしてやるわぁ～っ！", 3, 103401, 103402, "", "vo_empress_103401_004", "ユカリ", 1, 5, 128);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_103601_001", "ここで私たちが諦めたら、このまま\n世界が終わっちゃう！　そんなの\n絶対ダメです！　負けられません！\n私たちで全部退治しちゃいますよ！", 1, 0, 103603, "", "vo_empress_103601_001", "キョウカ", 1, 5, 129);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_103601_002", "うぅ、ふしんしゃがいっぱいです！\n…でも、このくらいへっちゃらです\nお母さんが心配する前に、早く\n片付けておうちに帰りましょう！", 1, 0, 103603, "", "vo_empress_103601_002", "キョウカ", 1, 5, 130);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_103601_003", "あれが私たちの敵、幻境竜后…\nほ、本当に勝てるんでしょうか…？\n立ってるだけで体が震えて…でも、\n弱気になっちゃダメですよねっ…！", 2, 0, 103601, "", "vo_empress_103601_003", "キョウカ", 1, 5, 131);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_103601_004", "正直に言うと…まだ少し怖いです\n我慢したって怖くて体が震えます\nでも、あなたがいてくれるから…\n勇気だって同じくらい湧いてきます", 3, 103601, 103602, "", "vo_empress_103601_004", "キョウカ", 1, 5, 132);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_103701_001", "滅ぼすための力に、守るための力が\n屈するわけにはいかないよ。\nこの剣の誇りに賭けて、必ず止める\nさあ、来い！　ミクマ流が相手だ！", 1, 0, 103701, "", "vo_empress_103701_001", "トモ", 1, 5, 133);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_103701_002", "追いかけっこでもしようか\n鬼さんこちら♪　…って、まだ\n来るの！？　不意打ちされる側に\nなるのは趣味じゃないんだけどな！", 1, 0, 103701, "", "vo_empress_103701_002", "トモ", 1, 5, 134);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_103701_003", "踏み込めない…踏み込む隙がない…\n向きあってるだけで精一杯なんて…\nで、でも…こんなところで\n剣を捨てるわけにはっ…！", 2, 0, 103701, "", "vo_empress_103701_003", "トモ", 1, 5, 135);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_103701_004", "勝機は私の中にあったんだ…！\nあなたとの、\n一番強くて絶対に消えない絆\nそれが、あいつを倒す力をくれる！", 3, 103701, 103702, "", "vo_empress_103701_004", "トモ", 1, 5, 136);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_103801_001", "手ごわい相手ですね…\nでも、不思議と怖くありません\nあなたと力を合わせれば\n何とかなるって信じていますから", 1, 0, 103801, "", "vo_empress_103801_001", "シオリ", 1, 5, 137);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_103801_002", "あなたの応援で、私の胸に\n愛と希望が満ち溢れています…\n今こそ魔法狩人ピュアリー★シオリ\nに大変身する時なのかも…？", 1, 0, 103801, "", "vo_empress_103801_002", "シオリ", 1, 5, 138);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_103801_003", "とてつもない力ですね…\nでも、諦めたくありません\n何度だって立ち上がってみせます\n今までと同じように…！", 2, 0, 103803, "", "vo_empress_103801_003", "シオリ", 1, 5, 139);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_103801_004", "今の私に怖いものなんてありません\nあなたとの愛の力がありますから♪\n…少し舞い上がり過ぎですかね？\nふふ、気を引き締めてがんばります", 3, 103801, 103802, "", "vo_empress_103801_004", "シオリ", 1, 5, 140);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_104001_001", "進んで目立ちたくはないですけど…\nと、ともっ…友達を守るためなら！\nＢＢ団として、勇気を振り絞って…\n団長さんと一緒に戦います！", 1, 0, 104001, "", "vo_empress_104001_001", "アオイ", 1, 5, 141);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_104001_002", "いいい、一緒に戦う仲間がこんなに\nいてくれるなんて、こ、心強いの\n助太郎～っ！　私も末席で参加し…\nじゃなくてっ！　全力で戦います！", 1, 0, 104002, "", "vo_empress_104001_002", "アオイ", 1, 5, 142);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_104001_003", "ううっ、手も足も声も震えてます…\nで、でも逃げも隠れもしませんよっ\n逃げたらぼっちが廃ります！", 2, 0, 104003, "", "vo_empress_104001_003", "アオイ", 1, 5, 143);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_104001_004", "私はひとりぼっちじゃない…\n団長さんと繋がった絆があるから\nどんな敵だって怖くないですっ！\n行きましょう、団長さんっ！", 3, 104001, 104002, "", "vo_empress_104001_004", "アオイ", 1, 5, 144);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_104201_001", "やめてくれる気はなさそうです\nそれなら私も、絶対にここを\n動きはしません…！　だって\n私は……ワガママですからっ！", 1, 0, 104203, "", "vo_empress_104201_001", "チカ", 1, 5, 145);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_104201_002", "私の唱喚術は人を守るためのもの…\nこの世界の森羅万象を護るための\nもの。今こそ、声の限り歌います\nこの子たちと、あなたと共に！", 1, 0, 104201, "", "vo_empress_104201_002", "チカ", 1, 5, 146);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_104201_003", "精霊たちが震えてる…今までの\n敵とは訳が違うってことですよね…\n私もここに立っているのが精一杯…\n怖いけど…でも！　退きません…！", 2, 0, 104203, "", "vo_empress_104201_003", "チカ", 1, 5, 147);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_104201_004", "今なら歌える気がします。ずっと\n探していた、誰かの心を震わせる歌\n幻境竜后…孤独なあなたの心にも\n私たちの歌が届くように…！", 3, 104201, 104201, "", "vo_empress_104201_004", "チカ", 1, 5, 148);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_104301_001", "敵さんがどんだけ強くったって\n後には退けねぇんだ！　そうだろ、\nさぁ、覚悟しやがれよ！", 1, 0, 104301, "", "vo_empress_104301_001", "マコト", 1, 5, 149);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_104301_002", "くっ、敵の連中、ずいぶんな戦力\n揃えてきやがった。けど、\n数でも気合でも負けやしねぇ！\nあたしが嚙み砕いてやる！", 1, 0, 104301, "", "vo_empress_104301_002", "マコト", 1, 5, 150);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_104301_003", "幻境竜后とやら…マジで\n洒落になんねえな。だからって\n引き下がるわけにゃいかねえ！\n持ちこたえてやるぜ！", 2, 0, 104303, "", "vo_empress_104301_003", "マコト", 1, 5, 151);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_104301_004", "どんな強い敵でも\n恐れる必要なんてないよな\nさあ、いっしょに─最大パワーで\nブチのめしてやろうぜっ！", 3, 104301, 104302, "", "vo_empress_104301_004", "マコト", 1, 5, 152);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_104401_001", "ここはいずれわらわが支配する世界\nつまり、わが領地に等しきもの…\n奴らのような不届き者の蛮行、\n見過ごすわけにはいかぬわ！", 1, 0, 104401, "", "vo_empress_104401_001", "イリヤ", 1, 5, 153);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_104401_002", "厳しい戦いになりそうじゃな…\nお主もわらわから離れるでないぞ\nも、もちろん、大人の姿を保つのに\n都合がいいからというだけじゃ！", 1, 0, 104401, "", "vo_empress_104401_002", "イリヤ", 1, 5, 154);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_104401_003", "何とも恐ろしく禍々しい力じゃ…\nだが、我が意志は決して挫けぬ\n高貴なる吸血鬼の誇りに懸けて、\n最後まで戦い抜いてみせようぞ", 2, 0, 104401, "", "vo_empress_104401_003", "イリヤ", 1, 5, 155);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_104401_004", "己が誰を敵に回したのかを、\n骨の髄まで知らしめてやろうぞ\nここにいるのは固き絆で結ばれし\n伝説の吸血鬼とその眷属じゃ！", 3, 104401, 104401, "", "vo_empress_104401_004", "イリヤ", 1, 5, 156);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_104501_001", "とっても強そうな敵ですっ…\n当然、攻撃も強烈になるはず…\nドＳさん、ここはどうかクウカに、\n先頭をお任せください！　ぐふふ♪", 1, 0, 104501, "", "vo_empress_104501_001", "クウカ", 1, 5, 157);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_104501_002", "安心してドＳさんに虐げてもらう\nためにもクウカは負けられませんっ\nこの世界で一番のドＭとして、\n全力で責められに行ってきますっ！", 1, 0, 104501, "", "vo_empress_104501_002", "クウカ", 1, 5, 158);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_104501_003", "ううっ、刺激が強すぎますよ…っ\nだけど、ドＭのプライドにかけて\nここで退くわけにはいきませんっ！\nドＳさんのこと、守り抜きます…っ", 2, 0, 104503, "", "vo_empress_104501_003", "クウカ", 1, 5, 159);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_104501_004", "その視線は、『全部終わったらたっ\nぷり調教してやるからな』という\n意味ですね！　ぐふふっ…♪　負け\nられない理由がまた一つできました", 3, 104501, 104502, "", "vo_empress_104501_004", "クウカ", 1, 5, 160);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_104601_001", "強そうなやつらが目白押しにゃ～\n短期戦でどうにかならないなら…\n長丁場に向けて、特別価格の\nたい焼きはいかがかにゃ～？", 1, 0, 104601, "", "vo_empress_104601_001", "タマキ", 1, 5, 161);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_104601_002", "ファントムキャッツは\n狙った獲物を逃がさないにゃ！\nあたしたちの未来を手に入れるまで\nとことんやってやるにゃ～！", 1, 0, 104601, "", "vo_empress_104601_002", "タマキ", 1, 5, 162);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_104601_003", "にゃにゃっ、これが幻境竜后…\nとんでもない力だにゃ\nでも、ここで逃げたらファントム\nキャッツの名が廃るにゃ～！", 2, 0, 104603, "", "vo_empress_104601_003", "タマキ", 1, 5, 163);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_104601_004", "ファントムキャッツにかかれば\nどんなに強い悪党でも\n滅びる運命にゃ！\nとっておきの一撃、キメるにゃ～！", 3, 104601, 104602, "", "vo_empress_104601_004", "タマキ", 1, 5, 164);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_104701_001", "全軍展開！　敵の一体たりとも\nこの先へは進ませるな\n苦しいときは、私の背中を見るんだ\n我々は決して折れはしない！", 1, 0, 104701, "", "vo_empress_104701_001", "ジュン", 1, 5, 165);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_104701_002", "少年…\n最前線は危険だが、下がるつもりは\nないのか？　ふふ、やはり強情だな\nならば、私の隣を絶対に離れるな", 1, 0, 104701, "", "vo_empress_104701_002", "ジュン", 1, 5, 166);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_104701_003", "な…なんだ…この冷たい闘気は…！\nみんな、いったん退がれ！\n安心しろ、ここは私が防ぎきる\n…たとえ…この身に代えても", 2, 0, 104701, "", "vo_empress_104701_003", "ジュン", 1, 5, 167);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_104701_004", "幻境竜后、貴様は絶対に勝てないよ\n自分の身以上に、大切な誰かを\n守りたいという、人間の持つ尊い\n想いを、知ることのない貴様は…！", 3, 104701, 104701, "", "vo_empress_104701_004", "ジュン", 1, 5, 168);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_104801_001", "バイト仲間とこの世界のみんなを\n守るために！　私たちのやるべき\nことはただ一つ！　いいわね？\n─最高の効率で倒すわよ！", 1, 0, 104801, "", "vo_empress_104801_001", "ミフユ", 1, 5, 169);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_104801_002", "相手も数が多いし、短期決戦とは\nいかないわね…って！　早く\n勝たなきゃバイトに遅刻しちゃう\nもっと効率アップしていくわよ！", 1, 0, 104801, "", "vo_empress_104801_002", "ミフユ", 1, 5, 170);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_104801_003", "幻境竜后……本当に圧倒的な力ね\nだからってそう簡単に諦められる\nわけはないわよね。たとえそれが\n非効率的な判断だとしても……！", 2, 0, 104803, "", "vo_empress_104801_003", "ミフユ", 1, 5, 171);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_104801_004", "こんなに迂遠で非効率的な計画を\n立てる敵になんて負けないわ！\n効率を極めた私たちの一撃を\n叩きつけてやりましょう！", 3, 104801, 104802, "", "vo_empress_104801_004", "ミフユ", 1, 5, 172);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_104901_001", "安心していいよ、弟くん♪\n弟くんには指一本触れさせない！\n絶対に弟くんを守るから…だって\nそれがお姉ちゃんの役目だもんね！", 1, 0, 104902, "", "vo_empress_104901_001", "シズル", 1, 5, 173);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_104901_002", "準備はできてる、弟くん？\n不安なら手をつないであげよっか？\n大丈夫、お姉ちゃんと弟くんなら\n悪いやつらを全部倒せるはず♪", 1, 0, 104902, "", "vo_empress_104901_002", "シズル", 1, 5, 174);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_104901_003", "幻境竜后…手強そうだね…\nでも諦めないよ、絶対に！\n弟くんとお姉ちゃんの大切な世界\nきっと守り抜いてみせるんだから！", 2, 0, 104903, "", "vo_empress_104901_003", "シズル", 1, 5, 175);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_104901_004", "お姉ちゃんと弟くんの力を合わせて\n二人の未来を、みんなの未来を\n一緒に守ろっ！　あ、終わったら\nたくさん甘えさせてあげるからね♪", 3, 104901, 104902, "", "vo_empress_104901_004", "シズル", 1, 5, 176);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_105001_001", "アブナイキレイなお姉さんはね\n『ふれーばー』だから許されるの！\nこんなメチャクチャにするなんて…\n本物の大人のレディが勝負よ勝負！", 1, 0, 105001, "", "vo_empress_105001_001", "ミサキ", 1, 5, 177);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_105001_002", "アタシは全世界代表の\n大人のレディなんだから！\nアンタ！\nしっかりエスコートしてよね！", 1, 0, 105001, "", "vo_empress_105001_002", "ミサキ", 1, 5, 178);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_105001_003", "コ、コイツが幻境竜后…っ\n…正直怖いけど…絶対に逃げないわ\n大人のレディのプライドにかけて\n戦い抜いてやるんだから…！", 2, 0, 105003, "", "vo_empress_105001_003", "ミサキ", 1, 5, 179);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_105001_004", "終わったらデートよ！　だって…\n約束があった方がやる気出るもん♪\nよーし！　大人のレディとして\n最後はエレガントに決めるわよ！", 3, 105001, 105002, "", "vo_empress_105001_004", "ミサキ", 1, 5, 180);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_105101_001", "なんて重圧かしら…でも、あいにく\n私も伊達に修羅場をくぐってないの\nさあ、かかってきなさい！\n裏の人生経験、見せてあげるわ…♪", 1, 0, 105101, "", "vo_empress_105101_001", "ミツキ", 1, 5, 181);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_105101_002", "私は闇医者である前に科学者なの\nあなたたち、実験に協力してくれる\nわよね？　隻眼の悪魔の名は\n伊達じゃないのよ？　覚悟しなさい", 1, 0, 105101, "", "vo_empress_105101_002", "ミツキ", 1, 5, 182);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_105101_003", "到底不可能に思える挑戦こそ\n科学者の腕の見せどころなのよ\n青い薔薇のごとく、人の信念が\n起こす奇跡を見せてあげるわ…！", 2, 0, 105101, "", "vo_empress_105101_003", "ミツキ", 1, 5, 183);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_105101_004", "迷いのない言葉をもらったんだもの\n私だってもう、覚悟を決めたわ\nこの先の未来を君と生きていく…\nそのために全力をぶつけるだけよ！", 3, 105101, 105101, "", "vo_empress_105101_004", "ミツキ", 1, 5, 184);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_105201_001", "私のお友達をいじめるなら\n相手になるわ！\nたとえ魔物に間違えられても\n絶対にここを引かないから！", 1, 0, 105201, "", "vo_empress_105201_001", "リマ", 1, 5, 185);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, 1, "vo_empress_105201_002", "ね、ねぇ…\nちょっと聞きたいんだけど\n毛皮もないのにあの姿なのよね？\n風邪引いたりしないのかしら？", 4002, 0, 105201, 10000, "vo_empress_105201_002", "リマ", 1, 3, 186);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_105201_003", "ひづめは割れちゃいそうだし…\n毛並みだってボロボロだし…\nでも後ろには彼がいるんだもの\n恋する乙女の負けられない戦いよ！", 2, 0, 105201, "", "vo_empress_105201_003", "リマ", 1, 5, 187);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_105201_004", "私はもう恋する女の子じゃないわ…\n王子様の愛を受け取ったお姫様よ！\n彼が私を守ってくれるように\n私が彼を守ってみせるわ！", 3, 105201, 105202, "", "vo_empress_105201_004", "リマ", 1, 5, 188);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_105301_001", "どれほど強大な敵であろうと、\n我々【ヴァイスフリューゲル\nランドソル支部】がいれば安心…\nこら！　皆纏まって行動しろー！", 1, 0, 105303, "", "vo_empress_105301_001", "モニカ", 1, 5, 189);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_105301_002", "敵戦力は強大無比…だが、\n私たちなら必ず倒せるはずだ！\n白き翼の名のもとに、今こそ\n正義の鉄槌を下してやる！", 1, 0, 105301, "", "vo_empress_105301_002", "モニカ", 1, 5, 190);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_105301_003", "これが幻境竜后の底力か…\n名にし負う圧倒的な強さだな…\nだが！　長期戦になろうとも必ずや\n私たちが勝利の旗を掲げるのだ！", 2, 0, 105301, "", "vo_empress_105301_003", "モニカ", 1, 5, 191);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_105301_004", "貴公と一緒ならば\nなんだってできるとも\nさあ、最後の一撃を加えてやろう！", 3, 105301, 105302, "", "vo_empress_105301_004", "モニカ", 1, 5, 192);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_105401_001", "強そうな相手ばかりですけど\nだからなんだっていうんですか！\nほら、騎士さんも気合い入れて！\n一緒に戦いますよ！", 1, 0, 105401, "", "vo_empress_105401_001", "ツムギ", 1, 5, 193);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, 1, "vo_empress_105401_002", "なんか敵に下着姿…っていうか\nほぼ裸みたいな人いません？\n…え？　あれ趣味なんですか？\nあの人の？　…正気ですか？", 4002, 0, 105403, 10000, "vo_empress_105401_002", "ツムギ", 1, 3, 194);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_105401_003", "世界を作り変えようなんて\n幻境竜后、絶対許せません…！\nあとその服！　そんなに破いて！\nデザイナーが泣いてますよ！", 2, 0, 105403, "", "vo_empress_105401_003", "ツムギ", 1, 5, 195);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_105401_004", "私と騎士さんの糸は\n絶対に切れません！\nだから…今ここで\nすべてを終わらせましょう！", 3, 105401, 105401, "", "vo_empress_105401_004", "ツムギ", 1, 5, 196);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_105501_001", "つ、強そうな人たちばっかり…\n逃げたいくらいだけど、\nそれはダメ。先輩をケガさせない\nためにも、私も頑張らなくちゃ！", 1, 0, 105503, "", "vo_empress_105501_001", "アユミ", 1, 5, 197);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_105501_002", "私なんかが大それたことを言うのは\n笑われるかも…でも…！\n先輩を守るために、\n世界を守ってみせます…！", 1, 0, 105501, "", "vo_empress_105501_002", "アユミ", 1, 5, 198);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_105501_003", "な、なんて大きさ、存在感…！\nまるで私とは真逆の人…\nこうして立ってるだけで、\n私、消えちゃいそうです～っ…！", 2, 0, 105503, "", "vo_empress_105501_003", "アユミ", 1, 5, 199);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_105501_004", "先輩がそばにいてくれる…\nそれだけで勇気が湧いてきて\n前へ進む力がもらえるんです\n行きましょう、先輩！", 3, 105501, 105502, "", "vo_empress_105501_004", "アユミ", 1, 5, 200);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_105601_001", "雁首並べてよくもまあ…\nこりゃ長丁場になりそうだ\n釣りと同じくじっくり腰を据えて\n勝負しようじゃないか", 1, 0, 105601, "", "vo_empress_105601_001", "ルカ", 1, 5, 201);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_105601_002", "世界の危機とあっちゃあ\nアタシたち黄昏時の住人でも\n黙っちゃいられないね！\nひとっ働きさせてもらおうかい！", 1, 0, 105601, "", "vo_empress_105601_002", "ルカ", 1, 5, 202);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_105601_003", "へぇ、これが幻境竜后かい…\nたいそうな強さだけど、アタシも\nここで退くわけにはいかないんだ\n心に差した刃に懸けて、いくよ！", 2, 0, 105603, "", "vo_empress_105601_003", "ルカ", 1, 5, 203);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_105601_004", "刀も恋も揃ったアタシは天下無双！\nお前さんが側にいてくれれば、\nどんな巨悪にだって勝てるよ！", 3, 105601, 105602, "", "vo_empress_105601_004", "ルカ", 1, 5, 204);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_105801_001", "また一緒に、みんなで\nおいしいごはんを食べるために！\nわたしたちは、絶対に負けません！", 1, 0, 105803, "", "vo_empress_105801_001", "ペコリーヌ", 1, 5, 205);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, 1, "vo_empress_105801_002", "フレイヤさんだけじゃなく、\n覇瞳皇帝やミロクまで！\n長丁場になりそうです…\n栄養補給はしっかりしましょうね！", 4003, 0, 105801, 10000, "vo_empress_105801_002", "ペコリーヌ", 1, 3, 206);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_105801_003", "これが、幻境竜后の力…\nやばいですね。正直、どうやって\n止めればいいのか分かりません\nでもここで引き下がるわけには…っ", 2, 0, 105803, "", "vo_empress_105801_003", "ペコリーヌ", 1, 5, 207);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_105801_004", "あなたの愛情でお腹いっぱいの\n無敵ペコリーヌ参上です☆\nわたしたちの明日を、この世界を\n全力全開で取り戻しましょう！", 3, 105801, 105802, "", "vo_empress_105801_004", "ペコリーヌ", 1, 5, 208);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_105901_001", "みなさまとのおいしいごはんのため\n負けるわけにはまいりません\n主さま、お背中はお任せください\nわたくしがお守りいたします！", 1, 0, 105903, "", "vo_empress_105901_001", "コッコロ", 1, 5, 209);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_105901_002", "敵は強大…ですが、心強い仲間の\nみなさまが一緒でございます\n…全員主さまとお知り合いなのは\n未だに信じられませんが…", 1, 0, 105905, "", "vo_empress_105901_002", "コッコロ", 1, 5, 210);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_105901_003", "まだこのような力が…！？\n主さま、ここはお下がりください\nたとえこの身に何があろうと、\nあなただけはお守りいたします…！", 2, 0, 105903, "", "vo_empress_105901_003", "コッコロ", 1, 5, 211);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_105901_004", "主さまとの絆がある限り\nわたくしは絶対に負けません！\nいついかなるときも、何があろうと\nわたくしが導いてみせます！", 3, 105901, 105902, "", "vo_empress_105901_004", "コッコロ", 1, 5, 212);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, 1, "vo_empress_106001_001", "また陛下と戦うのね…大丈夫、一番\n大事なものが何なのかは分かってる\n…だから、あたしも負けないわ\n─陛下、よろしくお願いします！", 4005, 0, 106001, 10000, "vo_empress_106001_001", "キャル", 1, 3, 213);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_106001_002", "この世界を好き勝手しようだなんて\nそういう連中に人生振り回されるの\nこちとらもううんざりなのよ！\n全員ぶっ飛ばしてやるんだから！", 1, 0, 106003, "", "vo_empress_106001_002", "キャル", 1, 5, 214);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_106001_003", "なんなのよあの力、反則でしょ…\nだけどさ、どんなに怖くたって\nあたしはここから退かないわ\n他に行くとこも、ないんだからっ…", 2, 0, 106003, "", "vo_empress_106001_003", "キャル", 1, 5, 215);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_106001_004", "絆の力でパワーアップ、なんて\nガラじゃないと思ってたけど…\n今だけは調子に乗らせてもらうわ\nもう負ける気がしないってねっ！", 3, 106001, 106002, "", "vo_empress_106001_004", "キャル", 1, 5, 216);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_106101_001", "晶に直してもらって\n天楼覇断剣も新品同然だ！\n気合い入れていくぞオクトー！\nはーっはっはっはー！", 1, 0, 106102, "", "vo_empress_106101_001", "ノウェム", 1, 5, 217);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_106101_002", "真那、覚悟しとけよ！\nオマエが積み上げてきた悪事…\nこの大悪党がまとめて\nぶっ壊してやるからな！", 1, 0, 106101, "", "vo_empress_106101_002", "ノウェム", 1, 5, 218);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_106101_003", "今までの借り…ここでまとめて\n返してやるって、決めてたんだ\nオマエだけは絶対に、許さない\n…オマエが、どれだけ強くても…っ", 2, 0, 106103, "", "vo_empress_106101_003", "ノウェム", 1, 5, 219);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_106101_004", "大悪党のプリンセス？\nなんだかよくわからないけど──\nとにかく、あの化け物ぶった斬りに\n行くぞ！　ついてこい！", 3, 106101, 106102, "", "vo_empress_106101_004", "ノウェム", 1, 5, 220);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_106401_001", "絶対に負けられない戦いね\nおいしいごはんと、本当の\nハッピーエンドのために\n気を引き締めていきましょう", 1, 0, 106401, "", "vo_empress_106401_001", "シェフィ", 1, 5, 221);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, 1, "vo_empress_106401_002", "ミロク…まだ生きていたのね…！\nあの男は私が相手するわ\n兄さんの分もまとめて、\n今ここで借りを返さないと！", 4004, 0, 106403, 10000, "vo_empress_106401_002", "シェフィ", 1, 3, 222);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_106401_003", "こんな力を隠してたなんて…！\n…まだよ。まだ諦めないわ\nどんな方法を使ってでも\nみんなだけは助けてみせる…！", 2, 0, 106401, "", "vo_empress_106401_003", "シェフィ", 1, 5, 223);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_106401_004", "不思議ね…あなたとの思い出で\n全身に力が満ちていくような気持ち\n…私たちが紡いできた絆を\n幻境竜后に見せてやりましょう", 3, 106401, 106402, "", "vo_empress_106401_004", "シェフィ", 1, 5, 224);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_106501_001", "おまえら、ケンカ売りたいんだろ？\nこの世界そのものに！\nならこっち向けよ。喧嘩屋のオレが\nまとめて買ってやるぜ！", 1, 0, 106501, "", "vo_empress_106501_001", "カヤ", 1, 5, 225);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_106501_002", "オレがドラゴン族なのも、\nこんな力を持ってるのも…きっと\n今日、この時のためだったんだ\nそうだろ？", 1, 0, 106501, "", "vo_empress_106501_002", "カヤ", 1, 5, 226);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_106501_003", "ウソだろ…オレが竦んじまってる…\nアイツのあの赤い眼から、眼を\nそらすんじゃねぇ…！　ドラゴン族\nのケンカ最強は…オレ様だろッ…！", 2, 0, 106503, "", "vo_empress_106501_003", "カヤ", 1, 5, 227);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_106501_004", "自分の力に、ずっとビビッてた\nでも今は何よりこの力を頼もしく\n感じるぜ。テメェをぶっ倒し…\n明日を迎えるための力がなァ！", 3, 106501, 106501, "", "vo_empress_106501_004", "カヤ", 1, 5, 228);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_106601_001", "どきやがれです！　最強ギャングが\nおまえのシマ分捕りにきたですよ！\nこんだけ仲間がいりゃ楽勝ですね♪\n尻尾巻いて逃げ出しやがれです！！", 1, 0, 106603, "", "vo_empress_106601_001", "イノリ", 1, 5, 229);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_106601_002", "あっちもゾロゾロつれてきやがり\nましたね…へんっ、このあたしが\nビビビビるとでもおお思うですか\n…お、お兄さん、どどどこです？", 1, 0, 106601, "", "vo_empress_106601_002", "イノリ", 1, 5, 230);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_106601_003", "…！　あたしと同じドラゴン族？\nボスをプリンセスナイトに従えて\nたとか…へんっ、信じねーです！\nまあボスより性悪そ…ぴゃああっ", 2, 0, 106603, "", "vo_empress_106601_003", "イノリ", 1, 5, 231);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_106601_004", "ふっふっふ～ん！　熱い力が\nどんどん溢れてくるですよっ！\nさあ、懲らしめてやるですっ！\nおしりペンペンですよ！", 3, 106601, 106602, "", "vo_empress_106601_004", "イノリ", 1, 5, 232);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_106701_001", "ふふっ、強そうな子がいっぱいだね\nそれじゃあ、誰が一番か決めよっか\nヴィーちゃんのプリンセスナイトで\n歴代最強は誰なのかを、ね♪", 1, 0, 106701, "", "vo_empress_106701_001", "ホマレ", 1, 5, 233);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_106701_002", "ヴィーちゃんてば、そんな子たちと\n一緒にいるほうが楽しいんだ～？\nじゃ、私たちも見せつけないとだね\n遠慮なくやっちゃおう☆　あははっ", 1, 0, 106701, "", "vo_empress_106701_002", "ホマレ", 1, 5, 234);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_106701_003", "これが、ヴィーちゃんの本気…\nとってもとってもすごいなぁ\n怖がりだからこそ、そんなに\n強くなれちゃったのかな…", 2, 0, 106703, "", "vo_empress_106701_003", "ホマレ", 1, 5, 235);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_106701_004", "残念だけど、ヴィーちゃん…\nもうゲームオーバーみたいだよ\nあなたとのどんなゲームも私には…\n全部ドキドキして、楽しかったな", 3, 106701, 106702, "", "vo_empress_106701_004", "ホマレ", 1, 5, 236);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_106801_001", "毎度、予想を超える困難ばかり\n押し寄せてくるんだからさ～\nま、アタシと少年が居る以上、\n好きにはさせないよ、ってね！", 1, 0, 106802, "", "vo_empress_106801_001", "ラビリスタ", 1, 5, 237);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, 1, "vo_empress_106801_002", "よりによって真那まで相手かぁ…\nこりゃ一筋縄じゃいかなそうだ\n誰に対応するかは任せるけど、\n真那を相手取るなら頼ってよ", 4005, 0, 106801, 10000, "vo_empress_106801_002", "ラビリスタ", 1, 3, 238);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_106801_003", "当然、奥の手も用意してくるよね\n次から次へと用意周到だこと…\nとはいえこっちも負けられない\nこの難局の突破口を探すとしよう！", 2, 0, 106801, "", "vo_empress_106801_003", "ラビリスタ", 1, 5, 239);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_106801_004", "七冠…しかも幻境竜后が相手なら\n手は抜けそうにもないね\nはは、でもアタシたちならきっと\n乗り越えられーる！　だよね少年♪", 3, 106801, 106802, "", "vo_empress_106801_004", "ラビリスタ", 1, 5, 240);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, 1, "vo_empress_107001_001", "真那…ふふ、こんなところで相対\nすることになるとは。いつぞやの\n借り、返してあげますよ。用意は\nいいですね？　マサキも、貴方も", 4005, 0, 107001, 10000, "vo_empress_107001_001", "ネネカ", 1, 3, 241);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_107001_002", "数で私たちを圧倒しようなど…\n底の浅い戦略ですね。返り討ちに\nしてあげましょう…この世界を\nまだ失うわけにはいきませんから", 1, 0, 107001, "", "vo_empress_107001_002", "ネネカ", 1, 5, 242);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_107001_003", "この力…計算外ではありますが\nそれは予想外という意味では\nありません。ええ、楽しみましょう\n不可能を解く、方程式の探求を", 2, 0, 107001, "", "vo_empress_107001_003", "ネネカ", 1, 5, 243);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_107001_004", "特等席で観察させてもらいましょう\n貴方の『心』という変数が\n『レジェンドオブアストルム』に\nどのような影響を与えるのかを…", 3, 107001, 107002, "", "vo_empress_107001_004", "ネネカ", 1, 5, 244);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_107101_001", "クリスティーナさんのご登場だよ☆\nあっははは……☆　またとない宴だ\n心行くまで愉しもうじゃあないか\n血で血を洗うダンス…滾るな♪", 1, 0, 107101, "", "vo_empress_107101_001", "クリスティーナ", 1, 5, 245);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, 1, "vo_empress_107101_002", "真那さまがお出ましか…ワタシは\n本当に運がいいと見える♪　本気で\n刃を交える機会が巡ってくるなど\n願ってもない幸運だよ☆", 4005, 0, 107101, 10000, "vo_empress_107101_002", "クリスティーナ", 1, 3, 246);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_107101_003", "…ここで退くなど興冷めだろう？\nたとえ足が竦んだとしても…退屈に\n食われるよりもよほどいい！\n最後まで愉しみつくしてやるさ…☆", 2, 0, 107103, "", "vo_empress_107101_003", "クリスティーナ", 1, 5, 247);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_107101_004", "誤算だったなあ、『幻境竜后』\n他の者ならいざ知らず…\nキサマを殺せる唯一の力\n手にしたのはこの『誓約女君』だ！", 3, 107101, 107102, "", "vo_empress_107101_004", "クリスティーナ", 1, 5, 248);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_110801_001", "ざーす。世界を救う系の光バイトで\n来たんすけど…あ、説明とかは\n大丈夫っす。慣れてるんでノリで\n入れます─おのれ世界の敵め！", 1, 0, 110801, "", "vo_empress_110801_001", "クロエ", 1, 5, 249);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, 1, "vo_empress_110801_002", "なっつ、狐のねえさんいるじゃん\nまだ現役で悪モンやってたんだ\nてか中ボスポジに降格してるくね？\n世界の敵界隈、意外とせちがれーな", 4005, 0, 110801, 10000, "vo_empress_110801_002", "クロエ", 1, 3, 250);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_110801_003", "なんかヤベーの出てきたな…\nこのカンジ、若干最悪っていうか\nぶっちゃけ流れ変わったくない？\nこっから捲るのは…結構ダルいわ", 2, 0, 110803, "", "vo_empress_110801_003", "クロエ", 1, 5, 251);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_110801_004", "ちょ、聞いて敵、ウケんだけど\nなんかうち主人公だったみたいだわ\n山場でヒロインに力託され系のやつ\nてわけで、勝ち確いただきでーす", 3, 110801, 110802, "", "vo_empress_110801_004", "クロエ", 1, 5, 252);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_110901_001", "ちぇるーん☆　ボス敵のみんな～！\n初めまして＆お久しブリリアント！\n世界の美少女ちえるんでっす！\n今からぼっこぼこにしてあげるね！", 1, 0, 110901, "", "vo_empress_110901_001", "チエル", 1, 5, 253);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_110901_002", "クリスＰの敵はカルミナの敵！\nカルミナの敵はなかよし部の敵！\nツアー全通めざして戦います！\n現場の平和はチエルが守る！", 1, 0, 110901, "", "vo_empress_110901_002", "チエル", 1, 5, 254);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_110901_003", "あ、あのう…ヤバくないです？\n敵のねえさん、急に年末歌合戦の\nラスボス衣装みたくなりましたけど\nえ、どーしよ…揚げます白旗？", 2, 0, 110903, "", "vo_empress_110901_003", "チエル", 1, 5, 255);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_110901_004", "世界の敵さん、ごめんちゃい！\nなんか愛だか絆だかの超理論的な\nアレでチエル覚醒しちゃいました！\nちぇるっと終わらせてあげますね！", 3, 110901, 110902, "", "vo_empress_110901_004", "チエル", 1, 5, 256);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_111001_001", "世界の危機だって？　何度目だね？\nざまあみろだよ、勝手に滅べば…\nなに、地球の危機？　この箱庭の\n話ではなく？　何ソレ一大事！", 1, 0, 111001, "", "vo_empress_111001_001", "ユニ", 1, 5, 257);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_111001_002", "お、おい…敵が多すぎないか…？\n端の方でわちゃわちゃしてるだけの\n数合わせ要員として来たのだが…\nどういう事だ、聞いてた話と違うぞ", 1, 0, 111001, "", "vo_empress_111001_002", "ユニ", 1, 5, 258);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_111001_003", "あばば…なんだ、あの奇怪な姿は…\nあれが理系をこじらせた者の末路か\n宇宙暗黒理系女…どうしてあんなに\nなるまで放っておいたんだ…", 2, 0, 111003, "", "vo_empress_111001_003", "ユニ", 1, 5, 259);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_111001_004", "はん、驕ったな理系の女王よ\n世界は君が思うほど四角くない\n高機能計算機の弾いた数字ごときで\nぼくと彼の行間までは測れまいよ！", 3, 111001, 111002, "", "vo_empress_111001_004", "ユニ", 1, 5, 260);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_118001_001", "ですからわたくしは商人で、\n戦いなどは不向き…などと\n言ってる場合ではありませんわね！\n参りますわよ、我が陛下のために！", 1, 0, 118001, "", "vo_empress_118001_001", "クレジッタ", 1, 5, 261);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_118001_002", "ああもうはあもう、あっちこっち\n滅茶苦茶にしてくださってからに！\n復興費用の賠償はどなたに\n請求すればよろしいのかしら！？", 1, 0, 118003, "", "vo_empress_118001_002", "クレジッタ", 1, 5, 262);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_118001_003", "でっか！？　でっっっっか！！！\n幻境竜后でしたかしら！？\nなんなんですのあの高層建築な方、\n建築基準法違反ですわよ～っ！？", 2, 0, 118003, "", "vo_empress_118001_003", "クレジッタ", 1, 5, 263);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_118001_004", "ホーッホッホッホ！　幻境竜后さん\n貴方にはいらっしゃるのかしら！\n利害でなくその理想のために\n命を賭ける、真実の忠臣が！", 3, 118001, 118002, "", "vo_empress_118001_004", "クレジッタ", 1, 5, 264);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_118101_001", "恐ろしくて強そうな音が…たくさん\nでも…きっと、大丈夫。あなたや、\nミソラちゃん…みんなが一緒で…\nあたたかい音も、たくさんだもの…", 1, 0, 118101, "", "vo_empress_118101_001", "ランファ", 1, 5, 265);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_118101_002", "緊張、してる…？　そ、それなら、\nわたしに、任せて…わたし、歌を、\n歌うわね…聴けばきっと、いつも\n通りの力を、出せると思うから…", 1, 0, 118101, "", "vo_empress_118101_002", "ランファ", 1, 5, 266);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_118101_003", "お、音と声が、すごい…\nなんて…なんて恐ろしいのかしら…\n…？　で、でも…この音。\n幻境竜后も、恐怖…している…？", 2, 0, 118103, "", "vo_empress_118101_003", "ランファ", 1, 5, 267);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_118101_004", "わたしの歌が、どれほど役立つかは\nわからない…そ、それでもっ、\nあなたの力になりたいの…だから\nわたし、精一杯、歌うわね…", 3, 118101, 118102, "", "vo_empress_118101_004", "ランファ", 1, 5, 268);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, 1, "vo_empress_118201_001", "わー、ミロクさんや覇瞳皇帝さんも\nいるじゃないですか★\nそれじゃあわたしのガトリングで\nご挨拶といきましょっか♪", 4005, 0, 118201, 10000, "vo_empress_118201_001", "ミソラ", 1, 3, 269);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_118201_002", "騎士さんと力を合わせればどんな\n敵もほにゃららら～★　って感じで\nなんとかなると思うんですよねー\nほら、主人公補正ってやつで♪", 1, 0, 118201, "", "vo_empress_118201_002", "ミソラ", 1, 5, 270);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_118201_003", "復讐って、イイコトですかね？\n悪いコトですかね？まぁとりあえず\nぶっ壊してから考えましょうか\nね、幻境竜后さん─", 2, 0, 118202, "", "vo_empress_118201_003", "ミソラ", 1, 5, 271);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_118201_004", "騎士さんに選んでもらっちゃいまし\nたし、いらない縁とはバイバイした\nいんですよねー♪　ってわけで、\nここで終わりにさせてもらいます★", 3, 118201, 118202, "", "vo_empress_118201_004", "ミソラ", 1, 5, 272);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_118501_001", "みなさんの力を信じて、\n私も全力でサポートします\n連携と創意工夫があれば、きっと\nこの難局も乗り越えられます！", 1, 0, 118501, "", "vo_empress_118501_001", "カリン", 1, 5, 273);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_118501_002", "過去最大級の強敵が現れました！\nギルド管理協会を代表して…\nあなたに討伐を依頼します！\n報酬はお望みのままに、ですよ♪", 1, 0, 118502, "", "vo_empress_118501_002", "カリン", 1, 5, 274);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_118501_003", "…っ。さすがの強敵ですね…\nだからこそ、焦りは禁物…です\nあらゆる事態を想定して、ギルドの\nみなさんを支援するのが私の仕事…", 2, 0, 118503, "", "vo_empress_118501_003", "カリン", 1, 5, 275);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_118501_004", "あなたと共に進めば\nどんな壁も越えられます\n私の、大切な人の無事を信じて…\n今こそ全力を尽くします！", 3, 118501, 118502, "", "vo_empress_118501_004", "カリン", 1, 5, 276);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_118601_001", "あんな奴らを野放しにしてたら\nこの世界が滅茶苦茶にされちゃう！\nでもまぁこれはこれでチャンスよ♪\n最っ高の悪戯の標的にしてあげる！", 1, 0, 118601, "", "vo_empress_118601_001", "ネビア", 1, 5, 277);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_118601_002", "私はただのガイド妖精、みんなに\n比べれば大した力も持ってない…\nでも悪戯妖精なりの意地があんのよ\nあいつらに一泡吹かせてやるわ♪", 1, 0, 118601, "", "vo_empress_118601_002", "ネビア", 1, 5, 278);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_118601_003", "幻境竜后、なんて力の持ち主なの\n正直きっついわ…でもまだやれる\n私はデータよ、壊れたって\nあんたを守る壁くらいにはなれる…", 2, 0, 118603, "", "vo_empress_118601_003", "ネビア", 1, 5, 279);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_118601_004", "覚悟しなさいっ！\n出来損ないの悪戯妖精をなめたら\n痛い目に遭うって教えてあげる\nさぁ、最高のショーの始まりよ！", 3, 118601, 118602, "", "vo_empress_118601_004", "ネビア", 1, 5, 280);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_122301_001", "むー！　いたずらっこの暴れんぼ\nさんたちは、ヴァンピィちゃんが\nきつーくおしおきしちゃうよ！\n真祖のおつとめですから！", 1, 0, 122303, "", "vo_empress_122301_001", "ヴァンピィ", 1, 5, 281);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_122301_002", "けんぞくはヴァンピィちゃんの\n背中に隠れてなさいっ。え？\n背中を守りたい？　うん、それなら\nよろしい！　一緒だよ、けんぞく！", 1, 0, 122302, "", "vo_empress_122301_002", "ヴァンピィ", 1, 5, 282);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_122301_003", "幻境竜后？　ふーんだ！\nベスちゃんのほーが、ずーっと\n強くてカッコいいですし！\nいくよっ、けんぞくぅ！", 2, 0, 122303, "", "vo_empress_122301_003", "ヴァンピィ", 1, 5, 283);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_122301_004", "ここはみんなの『いばしょ』！\n壊しちゃうなんて、許さないもん\nヴァンピィちゃん、本気で怒ったよ\nやっちゃうよ、けんぞく！", 3, 122301, 122302, "", "vo_empress_122301_004", "ヴァンピィ", 1, 5, 284);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_123001_001", "ほら、あんたは余計な心配しないの\nあいつらに好き勝手させないように\n全力でぶつかっていくだけよ\nあたしたちの未来のためにね♪", 1, 0, 123002, "", "vo_empress_123001_001", "アメス", 1, 5, 285);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_123001_002", "…あの連中も強くてやばいけど…\n一番やばいのは、こんなにたくさん\n女の子の知り合いがいる\nあんたかもしれないわね…", 1, 0, 123001, "", "vo_empress_123001_002", "アメス", 1, 5, 286);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_123001_003", "なんて相手なの…さすがに想定を\n超えてるわよ…こんなの卑怯よね\nだからってここで逃げやしないわよ\nせめて、あんたを守るくらいは…！", 2, 0, 123003, "", "vo_empress_123001_003", "アメス", 1, 5, 287);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_123001_004", "敵がどれだけ強くたって関係ないわ\nあんたの行く道はあたしが照らす\n迷ったらあたしを見なさい\nどこまでだって導いてあげる！", 3, 123001, 123002, "", "vo_empress_123001_004", "アメス", 1, 5, 288);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_123301_001", "『レギオンウォー』思い出すな～\nあん時は敵側だったけどー\n今回は騎士きゅんたちの隣で\nネアおねえちゃんもがんばるぞ～♡", 1, 0, 123301, "", "vo_empress_123301_001", "ネア", 1, 5, 289);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_123301_002", "だる～、激ヤバなテキばっかじゃん\n騎士きゅんパワー充電しねーと\nおねえちゃんもギリギリかもー\nとりま、ちゅっちゅ♡　してい？", 1, 0, 123301, "", "vo_empress_123301_002", "ネア", 1, 5, 290);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_123301_003", "激ヤバドラゴン、ガチしんどー…\nま、だからって負ける気ねーけど\nこーゆう時こそ、スライムの\n粘り強さの見せ所っしょ～　ね♪", 2, 0, 123303, "", "vo_empress_123301_003", "ネア", 1, 5, 291);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_123301_004", "ンフフフフ～♪　今のアタシ、\n騎士きゅんと一心同体ってやつ～？\nめちゃめちゃアガるわ～♪\n愛の力パねぇ～♡", 3, 123301, 123302, "", "vo_empress_123301_004", "ネア", 1, 5, 292);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_126401_001", "ビーッ！　ビーッ！\nあっちもこっちもそっちも\n強そうな人たちでいっぱいですっ！\nセンサーが壊れちゃいそう～っ！", 1, 0, 126401, "", "vo_empress_126401_001", "クローチェ", 1, 5, 293);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_126401_002", "世界が大変なことになってますっ！\nでもわたしたちは今までだって、\n大変な戦いを乗り越えてきましたっ\nきっと…ううん、絶対勝てますっ！", 1, 0, 126401, "", "vo_empress_126401_002", "クローチェ", 1, 5, 294);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_126401_003", "ビビービビビーッ！　…ひゃあっ！\nセンサーが壊れちゃいました…！\nしかも、照準が震えちゃって…\n…これが…この感情が、恐怖…？", 2, 0, 126403, "", "vo_empress_126401_003", "クローチェ", 1, 5, 295);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_126401_004", "今のわたしたちに、怖いものなんて\nありませんっ！　敵さんがどんなに\n強くても…わたしとナイトさんの\n特別なパワーは、もっと強いです！", 3, 126401, 126402, "", "vo_empress_126401_004", "クローチェ", 1, 5, 296);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_126501_001", "ジオ・テオゴニアの姫として\nこの星に生きる一個として\nこれ以上の蹂躙を許すわけには\nいきません。そうですね？　騎士", 1, 0, 126501, "", "vo_empress_126501_001", "ライラエル", 1, 5, 297);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, 1, "vo_empress_126501_002", "穢らわしい、色狂いの山羊めが\n我が従僕を傀儡としてくれた借り、\n兆倍──否、京倍にして\n返してくれようぞ。崩雷夜天！", 4002, 0, 126506, 10000, "vo_empress_126501_002", "ライラエル", 1, 3, 298);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_126501_003", "幻境竜后。迷いなく、圧倒的な力で\nわたしたちの調和を滅しようとする\nそんな力を、認めたくはないのに…\nなんて、困難な戦いなのでしょう…", 2, 0, 126503, "", "vo_empress_126501_003", "ライラエル", 1, 5, 299);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_126501_004", "この星には、あなたがいる…\n悪辣な侵略者と戦う理由など、\nただそれだけで十分です\n守りましょう。わたしたちの世界を", 3, 126501, 126502, "", "vo_empress_126501_004", "ライラエル", 1, 5, 300);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, 1, "vo_empress_127701_001", "あそこにヴルムを傷つけた人が…！\n…騎士さん、絶対勝ちましょうね\nあの人たちのやったこと、私\n絶対ぜったい許しませんから！", 4002, 0, 127701, 10000, "vo_empress_127701_001", "リンド", 1, 3, 301);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_127701_002", "騎士さんたちと出会えたこの世界を\n悪いことになんか使わせません\n作り物だなんて信じられませんけど\n失っちゃいけないものはわかります", 1, 0, 127701, "", "vo_empress_127701_002", "リンド", 1, 5, 302);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_127701_003", "まだこんな力が残ってるの…！？\n考えなきゃ、私にできること…\n何か…何かないの…！？\nまた私、何もできないの…？", 2, 0, 127703, "", "vo_empress_127701_003", "リンド", 1, 5, 303);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_127701_004", "あなたが側にいてくれるから、\n私もこうして戦えます\nチョロいって言われてもいいです\n私にとって、大切なひとですから", 3, 127701, 127702, "", "vo_empress_127701_004", "リンド", 1, 5, 304);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_127801_001", "…正直、サボりとかじゃなくて…\nぜんぜん身体はきついです。でも…\n姉貴やみんなと過ごすこの世界は\n誰にも壊させやしませんから…！", 1, 0, 127801, "", "vo_empress_127801_001", "ヴルム", 1, 5, 305);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, 1, "vo_empress_127801_002", "騎士さん…アルシャトのこと\nあたしにも一発殴らせてください\nふざけた真似してくれたお礼…\n倍にして返してやりますよ", 4002, 0, 127801, 10000, "vo_empress_127801_002", "ヴルム", 1, 3, 306);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_127801_003", "冗談きついです、こんなの…\n勝てっこないじゃないですか\nあたしだってドラゴン族なのに\nこれほどまでに差があるだなんて…", 2, 0, 127803, "", "vo_empress_127801_003", "ヴルム", 1, 5, 307);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_127801_004", "もう後先考えずにいきますよ\n面倒見てくれる人がここにいるので\nあたしと騎士さんが揃えば\n無敵だってとこ見せてやります", 3, 127801, 127802, "", "vo_empress_127801_004", "ヴルム", 1, 5, 308);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, 1, "vo_empress_129001_001", "覇瞳皇帝…わたしの邪魔をするなら\nかつてのように、消去するだけ\nミロクも…わたしを草野優衣の\n複製と呼んだこと、後悔させてやる", 4005, 0, 129001, 10000, "vo_empress_129001_001", "エリス", 1, 3, 309);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_129001_002", "管理者の座は失っても\nわたしの意志は揺らがない…\n騎士クンの物語を紡ぐために…\nそれが、わたしの全てだから", 1, 0, 129001, "", "vo_empress_129001_002", "エリス", 1, 5, 310);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_129001_003", "これが七冠、幻境竜后の全力…\n管理者だったかつてのわたしを、\n超えるほどの脅威…でも、\n騎士クンだけは、守ってみせる…", 2, 0, 129003, "", "vo_empress_129001_003", "エリス", 1, 5, 311);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_129001_004", "孤独も絶望も越えてきた\nもうどんな闇にも迷わない\n騎士クンが隣にいる限り\nわたしは、負けない", 3, 129001, 129002, "", "vo_empress_129001_004", "エリス", 1, 5, 312);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_129601_001", "リアを──媛を、傷つけたひとたち\n笑ってられるのも今だけです──\nアルラウネの棘の鋭さ、\n教えてあげますから──", 1, 0, 129601, "", "vo_empress_129601_001", "アネモネ", 1, 5, 313);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_129601_002", "騎士のひと──背中は、任せます\n貴方のこと、\n媛と同じくらい、信じてるので──\n自分でも、びっくりですけど", 1, 0, 129601, "", "vo_empress_129601_002", "アネモネ", 1, 5, 314);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_129601_003", "私、ずっと抗ってきたんです\nそのために、強くなったはず──\nだから──諦めたく、ないです…", 2, 0, 129603, "", "vo_empress_129601_003", "アネモネ", 1, 5, 315);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_129601_004", "体が熱くて、思考がまとまらなくて\nなのに負ける気がしない──なんて\nよくわからないです。どうしてか、\n後で教えてください──騎士のひと", 3, 129601, 129601, "", "vo_empress_129601_004", "アネモネ", 1, 5, 316);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_129701_001", "難敵強敵揃い踏みなれど\nわっちらが退く理はありんせん\n騎士殿や、手を携えて此度の争乱\n鎮めて見せましょう也", 1, 0, 129701, "", "vo_empress_129701_001", "ネフィ＝ネラ", 1, 5, 317);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_129701_002", "今のわっちが萎弱であろうとて\n貴様等如き梟悪に斃される訳には\nゆかぬ也。再び足甲を舐めさせ\n地に臥すまで仕置きを致しんしょう", 1, 0, 129701, "", "vo_empress_129701_002", "ネフィ＝ネラ", 1, 5, 318);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_129701_003", "我が矜持『不退転』─如何なる敵で\nあろうとも揺らぐ仕儀はなし。斯様\nな邪竜程度、退けむと思い侍りしが\n─難儀な由、残念至極─…", 2, 0, 129703, "", "vo_empress_129701_003", "ネフィ＝ネラ", 1, 5, 319);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_129701_004", "参りまする也、騎士殿や\n懼るること等何一つ御座りんせん\n唯わっちらの勇儀を以て、此の星の\n明日を再び…掌中に致しんしょう", 3, 129701, 129702, "", "vo_empress_129701_004", "ネフィ＝ネラ", 1, 5, 320);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, 1, "vo_empress_130001_001", "─おや、フレイヤじゃないか\nずいぶん様変わりしたようだが\n今の方がアタシとしちゃ好みだね\nお礼参りのしがいもあるってもんさ", 4003, 0, 130001, 10000, "vo_empress_130001_001", "ヤマト", 1, 3, 321);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_130001_002", "…フゥン？　あっちもこっちも\n『王家の装備』を持ってるらしいね\n宝の山ってのはこのことかい\nまとめて搔っ攫ってやろうかね…！", 1, 0, 130001, "", "vo_empress_130001_002", "ヤマト", 1, 5, 322);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_130001_003", "ちっ…、幻境竜后つったかい\n世界を奪おうってのも冗談じゃ\nなさそうだ。…ワカナ、フブキ…\nお前たちだけでも、逃げな…", 2, 0, 130003, "", "vo_empress_130001_003", "ヤマト", 1, 5, 323);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_130001_004", "アタシらの住み家を奪おうだぁ？\nハッ、笑わせてくれるね\n盗賊は盗むモンであって、\n盗まれるモンじゃあないンだよ！", 3, 130001, 130002, "", "vo_empress_130001_004", "ヤマト", 1, 5, 324);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_130101_001", "つ、強そうな人たちがたくさん…\nなのに姉さんもフブキちゃんも\nやる気満々だし…\nわたし、どうすればいいのぉ～っ", 1, 0, 130101, "", "vo_empress_130101_001", "ワカナ", 1, 5, 325);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_130101_002", "きっと、長期戦になりますよね…\nあ、あの…ご飯、食べませんか？\nお腹が空くといけないと思って、\n作ってきたので…よろしければっ", 1, 0, 130101, "", "vo_empress_130101_002", "ワカナ", 1, 5, 326);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_130101_003", "む…むりっ！　無理ですよ～っ！\nあんなおっきいドラゴンなんて、\n勝てるわけないじゃないですかっ\nに、逃げちゃいましょ、ねっ…！？", 2, 0, 130103, "", "vo_empress_130101_003", "ワカナ", 1, 5, 327);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_130101_004", "と、盗られるぐらいなら盗るのが\n【バンディ・シスターズ】流ですっ\n騎士さん、わたしたちの未来を\n掴み取りにいきましょう…っ！", 3, 130101, 130102, "", "vo_empress_130101_004", "ワカナ", 1, 5, 328);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_130201_001", "だる～、ささっと片付けてきてよ～\nムリ？　知ってる～だってザコザコ\nお兄さんだもんね♪　しょーがない\n助けてあげよっかな～？きゃはは♡", 1, 0, 130201, "", "vo_empress_130201_001", "フブキ", 1, 5, 329);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_130201_002", "あの陰気ダサダサメガネさー、\n仲間集めてチョーシ乗ってねー？\nザコは何匹集まったってザコだって\nフブキちゃんが教えてあげまーす♪", 1, 0, 130201, "", "vo_empress_130201_002", "フブキ", 1, 5, 330);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_130201_003", "ふぇぇ…まじムリ、アイツムリ～！\n全然ラスボスってカンジじゃん！？\nぼくお家かえるぅ～っ！\nお兄さんも一緒にかえろっ、ねっ？", 2, 0, 130203, "", "vo_empress_130201_003", "フブキ", 1, 5, 331);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_130201_004", "お兄さん、やる気漲っちゃってる？\nだよねー、世界が滅んじゃったら\nぼくとも永遠のお別れなんだし？\n必死になるのもトーゼンっしょ～♡", 3, 130201, 130202, "", "vo_empress_130201_004", "フブキ", 1, 5, 332);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_130901_001", "はわっ！？　すっごくすっごく\n悪そうな人達いっぱいですますぅ！\nかばばん君、警備員モードです！\nぴっぴーーーー！", 1, 0, 130901, "", "vo_empress_130901_001", "クルル", 1, 5, 333);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_130901_002", "この戦いが終わったら、みなさんと\nパークで凱旋パレードですぅ♪\n…ふぇっ？\n気が早いですますか？", 1, 0, 130901, "", "vo_empress_130901_002", "クルル", 1, 5, 334);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_130901_003", "はわわっ！　幻境竜后さん、\n強そうすぎですっ…でもっ！\nやっと再建したパークも世界も\nぜったい壊させないですよ～っ！", 2, 0, 130903, "", "vo_empress_130901_003", "クルル", 1, 5, 335);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_130901_004", "ヒーローさんのこと、\nクルルの全部でお助けしますです！\nジオ・テオゴニアでも、どんな世界\nでも…ずっと、ず～っとですっ！", 3, 130901, 130902, "", "vo_empress_130901_004", "クルル", 1, 5, 336);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_132301_001", "なっなんなのよこいつらっ！\nダーリンとの恋路を邪魔する気…？\nそんなことさせないわ…だって、\n二人の恋はエターナルですからっ！", 1, 0, 132301, "", "vo_empress_132301_001", "ルイズマリー", 1, 5, 337);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_132301_002", "愛情×愛情＝無限大…\n遂に錬金術の神髄に辿り着いたわ…\nさあ…お見舞いしてやりましょう！\n私とダーリンの究極錬成をっ！", 1, 0, 132301, "", "vo_empress_132301_002", "ルイズマリー", 1, 5, 338);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_132301_003", "あ、あなたがどんなに強くても、\n私は逃げないわ！　ダーリンに\nちょっかいかける奴は絶対に\n許さないって決めてるから…っ！！", 2, 0, 132303, "", "vo_empress_132301_003", "ルイズマリー", 1, 5, 339);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_132301_004", "悪いけど速攻で終わらせちゃうわ！\n早く帰ってダーリンと心行くまで\n破廉恥な乳繰り合い…じゃなくて！\n愛を確かめ合うんだからっ！", 3, 132301, 132302, "", "vo_empress_132301_004", "ルイズマリー", 1, 5, 340);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_132401_001", "わわっ、敵がいっぱい！\nこれがクワガタだったら最高…よし\n新種のクワガタって事にしちゃお！\nあははっ！　待て待て～っ！！", 1, 0, 132401, "", "vo_empress_132401_001", "イロハ", 1, 5, 341);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_132401_002", "あはは、まだまだ出てくるね～！\nなら新しい技いっぱい\n試しちゃおっか…さあ、いくよ！\n──イスルギ流奥義っ！！", 1, 0, 132401, "", "vo_empress_132401_002", "イロハ", 1, 5, 342);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_132401_003", "あのおねーさんもなかなか良いツノ\n持ってるねえ♪　イロハが勝ったら\nルイちゃんと二人でクワガタ相撲\nごっこやってもらおっと！", 2, 0, 132401, "", "vo_empress_132401_003", "イロハ", 1, 5, 343);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_132401_004", "おねーさんがどんなに強くたって\nイロハは絶対に負けない！\nおじちゃんが見ててくれてる時の\nイロハは、サイキョーなんだから！", 3, 132401, 132402, "", "vo_empress_132401_004", "イロハ", 1, 5, 344);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_132501_001", "いや無理無理、戦いとか苦手過ぎる\n…でも君となら、奇跡起こせるかも\n…うわやば、今の忘れて\n若者みたいなこと言っちゃったよ…", 1, 0, 132501, "", "vo_empress_132501_001", "ソノ", 1, 5, 345);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_132501_002", "敵、まだいっぱいいるじゃん…\nはあ…残業したくないけど頑張るか\n全部終わったら君からのマッサージ\n期待しとくから、ね", 1, 0, 132501, "", "vo_empress_132501_002", "ソノ", 1, 5, 346);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_132501_003", "はあ…はあ…幻境竜后だっけ？\nルイちゃんの錬金術より\n出鱈目な強さだね…！\nでもまだまだ諦めない…いくよ！", 2, 0, 132503, "", "vo_empress_132501_003", "ソノ", 1, 5, 347);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_132501_004", "こんなに強い敵が相手でも\n諦めなきゃ勝てるんだって\n教えてくれたのは君だよ\nふふ…ありがとね、若者♪", 3, 132501, 132502, "", "vo_empress_132501_004", "ソノ", 1, 5, 348);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_133001_001", "うーわ。あっちもこっちも\nボス級だらけじゃないですか\nま、ヴァイオレット姫には\n指一本触れさせませんけどね", 1, 0, 133001, "", "vo_empress_133001_001", "グレイス", 1, 5, 349);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, 1, "vo_empress_133001_002", "リーザ…今度こそ、決着の時ね\nいくら頭数を揃えても私は…いえ\n私と騎士氏は絶対に負けないわ\nこの槍で、冥界に送り返してあげる", 4001, 0, 133003, 10000, "vo_empress_133001_002", "グレイス", 1, 3, 350);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_133001_003", "ぐっ…圧倒的ですね『幻境竜后』\nですが…決してあきらめません\n私には、生きていてほしい人が\nたくさんいますので…！", 2, 0, 133003, "", "vo_empress_133001_003", "グレイス", 1, 5, 351);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_133001_004", "とてつもない強敵を前にしてるのに\nまるで恐怖心を感じません…\n…恋とは、心霊現象よりも\n不思議なものらしいですよ", 3, 133001, 133002, "", "vo_empress_133001_004", "グレイス", 1, 5, 352);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_133101_001", "恐るべき方々ばかりです…\nですがわたくしは絶対に退きません\nジオ・ニヴルヘルの姫として\nこの世界を守ると決めたのです！", 1, 0, 133101, "", "vo_empress_133101_001", "ヴァイオレット", 1, 5, 353);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, 1, "vo_empress_133101_002", "リーザ…どうしてもわたくしたちの\n前に立ちはだかるというのですね\nならばわたくしも覚悟を決めました\nこの手であなたを、倒します…！", 4001, 0, 133101, 10000, "vo_empress_133101_002", "ヴァイオレット", 1, 3, 354);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_133101_003", "これが、彼女の本気の力…！\n異質で…故に、とても寂しい…\n本当の意味で彼女に届く声が、\nこの世界に存在するのでしょうか…", 2, 0, 133103, "", "vo_empress_133101_003", "ヴァイオレット", 1, 5, 355);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_133101_004", "あなたとの「繋がり」がある限り\n死が牙を剥くことはありません\n手を取り合い、共に参りましょう\nわたくしたちの未来のために！", 3, 133101, 133102, "", "vo_empress_133101_004", "ヴァイオレット", 1, 5, 356);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_133601_001", "フンっ、次から次へと…！　なら\n思う存分、大暴れしてやるから♪\nやっちゃうわよ、メドゥシアナ！\nアンタも！！", 1, 0, 133601, "", "vo_empress_133601_001", "メドゥーサ", 1, 5, 357);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_133601_002", "どこの誰だか知らないけれど、\nアタシの魔眼でまとめて石に…って\nきゃああああ！　こんなバケモン級\nなら先に教えときなさいよ～っ！", 1, 0, 133601, "", "vo_empress_133601_002", "メドゥーサ", 1, 5, 358);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_133601_003", "な…なんなの、アイツの『眼』…\nでもねっ、アタシはメドゥーサ\nゴルゴーンの、お姉ちゃんの妹よ！\n睨みあいで負けるわけがないわ！", 2, 0, 133603, "", "vo_empress_133601_003", "メドゥーサ", 1, 5, 359);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_133601_004", "知ってる？　蛇って執念深いのよ\nこの『眼』で見つけてやったわ\n幻境竜后、アンタが一番恐れること\nアタシとこいつが手をつなぐこと！", 3, 133601, 133602, "", "vo_empress_133601_004", "メドゥーサ", 1, 5, 360);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_134701_001", "この大地と大空を守るため、\n人の子らだけに任せてはおけません\n鳳凰のはばたきで、その野望ごと\n跡形もなく吹き飛ばしましょう！", 1, 0, 134701, "", "vo_empress_134701_001", "ホウオウ", 1, 5, 361);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_134701_002", "さあ皆さん、ここが正念場です！\n私がいれば楽勝圧勝間違いなし！\n…えっ？　私が先頭？　えーと…\nあっちょっと待って押さないで！", 1, 0, 134701, "", "vo_empress_134701_002", "ホウオウ", 1, 5, 362);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_134701_003", "羽が散って、ちっ、力が…\n幻境竜后、やるではないですか…\nしかし、私も不死鳥と呼ばれた身…\nただでやられは…ぴ、ぴよぉぉ～…", 2, 0, 134703, "", "vo_empress_134701_003", "ホウオウ", 1, 5, 363);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_134701_004", "幻境竜后、でしたか？\nあなたも運のない方ですね\n今の私は輪廻史上最強の鳳凰\nその鱗一つ残さず焼き尽くします！", 3, 134701, 134702, "", "vo_empress_134701_004", "ホウオウ", 1, 5, 364);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_134901_001", "ヲ～ッホッホ！　どいつもこいつも\n大層なおツラ構えしてますけどぉ？\nあたくし様の敵じゃありませんわ！\nほら馬ボーン！　お強化なさいな！", 1, 0, 134901, "", "vo_empress_134901_001", "カノン", 1, 5, 365);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_134901_002", "いってぇ～ですわ！　あたくし様の\nお美しいお肌を傷つけましたわね！\nまとめてお成敗して差し上げますわ\nついてらっしゃいな！　馬ボーン！", 1, 0, 134901, "", "vo_empress_134901_002", "カノン", 1, 5, 366);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_134901_003", "なんてタマですの…アースハイドラ\nよりデカいなんて聞いてませんわ！\nでも…ここでお尻尾巻いて逃げる\nなら、死んだ方がマシですわ…！", 2, 0, 134903, "", "vo_empress_134901_003", "カノン", 1, 5, 367);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_134901_004", "幻境竜后とやら、お覚悟なさいな\nあたくしと馬ボーンの前に立つなど\n100億万年お早いですわ！\n華麗にお成敗して差し上げますわ♪", 3, 134901, 134902, "", "vo_empress_134901_004", "カノン", 1, 5, 368);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_135501_001", "来たね、お姉さんの出番ってやつ♪\nキミと一緒に戦えるなんて、あたし\nテンション最高潮だよ！　あははっ\nさ、思いっきり暴れちゃおっか！", 1, 0, 135501, "", "vo_empress_135501_001", "アイラ", 1, 5, 369);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, 1, "vo_empress_135501_002", "あれが…覇瞳皇帝のオリジナルだね\nま、関係ないや。本物でも偽物でも\n今度こそ決着つけてあげるから！\nお姉さんの拳…燃え盛ってるよー！", 4005, 0, 135501, 10000, "vo_empress_135501_002", "アイラ", 1, 3, 370);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_135501_003", "幻境竜后…とんでもない相手だね\nあたしの拳だって届かないかも…\nそれでも、燃え尽きるまで戦うよ\nキミが信じてくれてる限り、ね！", 2, 0, 135503, "", "vo_empress_135501_003", "アイラ", 1, 5, 371);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_135501_004", "キミがいれば怖いものなし！\nお姉さん今、燃えに燃えてるよっ\n太陽より熱く燃える拳で…\n全部まとめてぶっ飛ばす！", 3, 135501, 135502, "", "vo_empress_135501_004", "アイラ", 1, 5, 372);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_135601_001", "どれほどの逆風の中にいても、\n諦めてはならない…そうだろう？\nかつて私が、他でもないキミたちに\nそう教えてもらったんだ…", 1, 0, 135601, "", "vo_empress_135601_001", "シナツ", 1, 5, 373);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_135601_002", "私はこの世界の人々と出会い、\n失ったはずの希望を見つけられた\n今度は私が、皆に希望を届ける番だ\nこの刃、存分に振るわせてくれ", 1, 0, 135601, "", "vo_empress_135601_002", "シナツ", 1, 5, 374);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_135601_003", "幻境竜后…私たちの世界を創造し、\nそして滅ぼそうとした張本人か…！\nその力がどんなに強大だとしても…\n私は…絶対に逃げたりなどしない！", 2, 0, 135603, "", "vo_empress_135601_003", "シナツ", 1, 5, 375);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_135601_004", "私の刃に、もはや一片の曇りもない\n皆と生きる未来を守り抜くために\n戦いつづける…ただそれだけだ\n─道を阻む者は全て斬り伏せる！", 3, 135601, 135602, "", "vo_empress_135601_004", "シナツ", 1, 5, 376);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, 1, "vo_empress_135801_001", "リ、リ、リーザちゃ…！\nリーザちゃはあてのこと、ヘタレの\nホジナシって思ってっかもだけど…\n前より成長したとこ、見せっから！", 4001, 0, 135801, 10000, "vo_empress_135801_001", "ユキノ", 1, 3, 377);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_135801_002", "田舎者で世間知らずなあてだけど…\n騎士さと一緒にいろんなとこ行って\n大切な思い出、いっぱいできたよ…\nだから守りてぇんだ、この世界…！", 1, 0, 135801, "", "vo_empress_135801_002", "ユキノ", 1, 5, 378);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_135801_003", "あ、あても、ちったぁでけぇけど…\n幻境竜后、で、でっかすぎ…！\nそ、それに竜まで…！　炎浴びたら\nあて、溶けちまうよぅ…！", 2, 0, 135803, "", "vo_empress_135801_003", "ユキノ", 1, 5, 379);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_135801_004", "「あてなんか」なんて、考えね…\n騎士さが信じてくれるなら、\nあてだって自分のこと、信じるよ\nあてと騎士さなら大丈夫、って…！", 3, 135801, 135802, "", "vo_empress_135801_004", "ユキノ", 1, 5, 380);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, 1, "vo_empress_135901_001", "リザ公…手前ェどの面下げて\n俺の前に出てきやがった\nまァいいさ、何聞いても今更だ\nここで落とし前つけてもらうぜ", 4001, 0, 135903, 10000, "vo_empress_135901_001", "サツキ", 1, 3, 381);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_135901_002", "いつ死んでもいいなんて\nもう思っちゃいねぇさ\nこの悪玉どもより、図太くしぶとく\n生き抜いてやろうじゃねぇか", 1, 0, 135901, "", "vo_empress_135901_002", "サツキ", 1, 5, 382);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_135901_003", "あれが幻境竜后か…\nハンパじゃねェや\nしゃあねぇ、こうなりゃ一丁\n死に花咲かすとするか", 2, 0, 135901, "", "vo_empress_135901_003", "サツキ", 1, 5, 383);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_135901_004", "世界だの未来だの現実だの…\n重いったらありゃしねぇぜ\n潰れるなよ、騎士公\n俺も一緒に担いでやっからさ", 3, 135901, 135902, "", "vo_empress_135901_004", "サツキ", 1, 5, 384);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_136001_001", "騎士さま、どうかご安心を…\nどれだけ厳しい運命が待って\nいたとしても…あなたのことは、\nわたしの糸が必ずお守りします", 1, 0, 136001, "", "vo_empress_136001_001", "アラクネ", 1, 5, 385);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, 1, "vo_empress_136001_002", "…？　あの金髪の女性、なんだか\n見覚えあるような気が…いえ\n騎士さまの敵は、わたしの敵です\nそれだけです…", 4003, 0, 136001, 10000, "vo_empress_136001_002", "アラクネ", 1, 3, 386);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_136001_003", "あれが幻境竜后さま…\nなんという恐るべき力\n…騎士さま、わたしの後ろに\n一度くらいは、庇えるはずです…", 2, 0, 136003, "", "vo_empress_136001_003", "アラクネ", 1, 5, 387);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_136001_004", "騎士さまという光が、わたしに力を\n与えてくれるのです。ともに未来を\n歩むためにも…この戦いに\n必ず勝ちましょう、騎士さま", 3, 136001, 136002, "", "vo_empress_136001_004", "アラクネ", 1, 5, 388);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_136201_001", "強そうな敵さんがいっぱい～っ！？\nこーなったら、ウルトラとっておき\nドーナツ！　ちょっと湿気てるけど\n…はい騎士ちゃん、あーんっ♪", 1, 0, 136201, "", "vo_empress_136201_001", "ナーナ", 1, 5, 389);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_136201_002", "ナーナだって頑張れるんだよっ！\n騎士ちゃんに、そう教わったもん！\nだから、すごく怖いけど…でもっ…\nナーナ、逃げたりしないよぉっ！", 1, 0, 136201, "", "vo_empress_136201_002", "ナーナ", 1, 5, 390);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_136201_003", "うぅ…あ、足が震えてきちゃった…\nでも動かなきゃ、戦わなきゃっ…\nわかってるのに、でもでもぉ…\nうえぇぇん、やっぱり怖いぃぃ！", 2, 0, 136201, "", "vo_empress_136201_003", "ナーナ", 1, 5, 391);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_136201_004", "今のナーナはよわよわウサギじゃ\nないんだよ。騎士ちゃんのためなら\nどんな敵さんだってやっつけちゃう\nつよつよウサギなんだから！", 3, 136201, 136202, "", "vo_empress_136201_004", "ナーナ", 1, 5, 392);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, 1, "vo_empress_136901_001", "リーザ姉しゃまが裏切ったなんて\nあたち、信じたくないでしゅ…！\nだから直接聞きにいきましゅ\n吸盤ぜんぶで捕まえてでも…！", 4001, 0, 136903, 10000, "vo_empress_136901_001", "ルルィ", 1, 3, 393);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_136901_002", "姫姉しゃまも騎士しゃんも\nみなしゃん戦ってるんでしゅ\nあたちだって負けましぇん！\n一生懸命がんばりましゅ～！", 1, 0, 136901, "", "vo_empress_136901_002", "ルルィ", 1, 5, 394);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_136901_003", "あ、あの方、こわいでしゅ…！\n丸呑みにされちゃいそうでしゅっ\nうじゅ…がんばりたいでしゅが…\n震えが止まらないでしゅ…！", 2, 0, 136903, "", "vo_empress_136901_003", "ルルィ", 1, 5, 395);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_136901_004", "あたちは強くないでしゅけど\n騎士しゃんとの約束がありましゅ\nだから誰にも負けましぇん！\nいっちょに、守りましゅよ！", 3, 136901, 136902, "", "vo_empress_136901_004", "ルルィ", 1, 5, 396);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_139501_001", "これから挑む敵がどれだけ強いと\nしても、勇往邁進していきます\nですからこの戦いでも、兄様の\nおそばで戦わせてくださいませ", 1, 0, 139501, "", "vo_empress_139501_001", "リリ", 1, 5, 397);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, 1, "vo_empress_139501_002", "幻境竜后の手先、アルシャト…！\nリアさんやヴルム様を陥れた貴方を\n決して許す訳には参りません！\n不倶戴天─ここで成敗致します！", 4002, 0, 139503, 10000, "vo_empress_139501_002", "リリ", 1, 3, 398);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_139501_003", "幻境竜后の力…これほどまでに\n強力無比だとは…で、ですが…\n何があろうとわたくしは兄様を\nお守りします…命に代えても、必ず", 2, 0, 139503, "", "vo_empress_139501_003", "リリ", 1, 5, 399);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_139501_004", "兄様への想いと、重ねてきた大切な\n時間が、たくさんの勇気と限界を\n超える奇跡をくれました。全ての人\nを救うため、参りましょう兄様…！", 3, 125801, 139502, "", "vo_empress_139501_004", "リリ", 1, 5, 400);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_139601_001", "お兄さん、もし怪我しちゃっても\nすぐに治癒しますからご安心を！\nわたし決めましたから…もう二度と\n自分自身から逃げないって…！", 1, 0, 139603, "", "vo_empress_139601_001", "クリア", 1, 5, 401);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, 1, "vo_empress_139601_002", "…アルシャトさん…\n謝ったって許してあげませんよ？\nあなたの前では、わたしちょっと\nいい子じゃいられませんから…っ！", 4002, 0, 139603, 10000, "vo_empress_139601_002", "クリア", 1, 3, 402);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_139601_003", "うぅっ…これが本気の幻境竜后…！\n…こんなの勝てっこありませんよ…\n…せめてお兄さんだけでも…なんて\n最後まで…諦めませんからっ…！", 2, 0, 139603, "", "vo_empress_139601_003", "クリア", 1, 5, 403);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_139601_004", "お兄さんの気持ちが胸に溢れて…\nあ、えへへ…なんだか視界が\n滲んできちゃいました…♪\nわたしはもう、負けませんよ…っ！", 3, 126001, 139601, "", "vo_empress_139601_004", "クリア", 1, 5, 404);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_139701_001", "てき、いっぱい、しかも、つよすぎ\nけど、まけないよ\nお兄のほっぺ、たべて\nふるぱわー", 1, 0, 139701, "", "vo_empress_139701_001", "プレシア", 1, 5, 405);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_139701_002", "ん\nまだまだ、いける\nお兄、パパ、なかま、いる\nむしゃぶるい", 1, 0, 139701, "", "vo_empress_139701_002", "プレシア", 1, 5, 406);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_139701_003", "しょうり、みえない\nせいぎ、まもれない\nそんなの、いや\nあきらめないよ、さいごまで", 2, 0, 139703, "", "vo_empress_139701_003", "プレシア", 1, 5, 407);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_139701_004", "て、つなぐ\nせいめいりょく、たかまる\nぜったいしょうり！", 3, 126101, 139702, "", "vo_empress_139701_004", "プレシア", 1, 5, 408);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4, "", "vo_empress_140301_004", "七冠、幻境竜后──LoAの開発者\nあんたにコワいコト教えてあげるわ\n些細なバグと思って放置したら\nゲームを壊すこともあるってね…♪", 3, 140301, 140301, "", "vo_empress_140301_004", "ティア", 1, 5, 409);
